  private static final class FixtureInvocation {
    final int ordinal, variantOrdinal;
    final String method, variant, key, displayLabel;
    volatile boolean passed, afterEachComplete;
    final java.util.Set<Long> sessionOrdinals = java.util.concurrent.ConcurrentHashMap.newKeySet();

    FixtureInvocation(int ordinal, String method, String variant, int variantOrdinal) {
      this.ordinal = ordinal;
      this.method = method;
      this.variant = variant;
      this.variantOrdinal = variantOrdinal;
      displayLabel = variant.equals("singleton") ? method + "()" : "incremental joined " + variant;
      key = FIXTURE_PROFILE.lane + "-" + ordinal + "-" + method + "-" + variant;
    }
  }

  private static final List<FixtureInvocation> FIXTURE_INVOCATIONS = new CopyOnWriteArrayList<>();
  private static volatile FixtureInvocation activeFixtureInvocation;
  private static final java.util.concurrent.ConcurrentMap<String, FixtureInvocation>
      SESSION_INVOCATIONS = new java.util.concurrent.ConcurrentHashMap<>();

  private record ModelCallKey(String sessionId, String requestId, int attempt) {}

  private record ModelCallJoin(
      FixtureInvocation invocation,
      String sessionId,
      long sessionOrdinal,
      long attemptOrdinal,
      String kind,
      long inputCeiling,
      int outputCeiling,
      int responseBound) {}

  private static final java.util.concurrent.ConcurrentMap<ModelCallKey, ModelCallJoin>
      MODEL_CALL_JOINS = new java.util.concurrent.ConcurrentHashMap<>();
  private static final List<ObjectNode> MODEL_RESPONSE_FACTS = new CopyOnWriteArrayList<>();
  private static final java.util.concurrent.ConcurrentMap<ModelCallKey, ObjectNode>
      MODEL_RESPONSE_JOINS = new java.util.concurrent.ConcurrentHashMap<>();

  private static void beginFixtureInvocation(TestInfo info) {
    String method = info.getTestMethod().orElseThrow().getName();
    String variant = "singleton";
    int variantOrdinal = 0;
    if (method.equals("incrementalStructuralEditsAndExplicitRelearningUseTheActualJoinedBrowser")) {
      String display = info.getDisplayName();
      variant =
          INCREMENTAL_VARIANTS.stream()
              .filter(label -> display.equals("incremental joined " + label))
              .findFirst()
              .orElseThrow(() -> new IllegalStateException("Unrecognized closed JOIN invocation"));
      variantOrdinal = INCREMENTAL_VARIANTS.indexOf(variant) + 1;
    } else {
      assertThat(SINGLETON_METHODS.contains(method)).isTrue();
      assertThat(info.getDisplayName()).isEqualTo(method + "()");
    }
    assertThat(INCREMENTAL_METHODS.contains(method))
        .as("the closed profile owns exactly its declared methods")
        .isEqualTo(FIXTURE_PROFILE == FixtureProfile.INCREMENTAL_2048);
    var invocation =
        new FixtureInvocation(FIXTURE_INVOCATIONS.size() + 1, method, variant, variantOrdinal);
    FIXTURE_INVOCATIONS.add(invocation);
    activeFixtureInvocation = invocation;
  }

  private static void privateImmutableJson(Path path, JsonNode value) throws Exception {
    Files.createDirectories(path.getParent());
    byte[] bytes = GuidedContracts.canonical(value).getBytes(StandardCharsets.UTF_8);
    try (var channel =
        Files.newByteChannel(
            path,
            java.util.Set.of(
                java.nio.file.StandardOpenOption.CREATE_NEW,
                java.nio.file.StandardOpenOption.WRITE),
            java.nio.file.attribute.PosixFilePermissions.asFileAttribute(
                java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")))) {
      var buffer = java.nio.ByteBuffer.wrap(bytes);
      while (buffer.hasRemaining()) {
        channel.write(buffer);
      }
    }
  }

  private static void assertDeclaredFixtureCeiling(long actual) {
    if (FIXTURE_PROFILE == FixtureProfile.ORIGINAL_4000) {
      assertThat(actual).isEqualTo(4000);
    } else {
      assertThat(actual).isEqualTo(2048);
    }
  }

  private static void retainResponseFacts(FixtureInvocation invocation, String phase)
      throws Exception {
    ObjectNode out =
        C.object()
            .put("lane", FIXTURE_PROFILE.lane)
            .put("method", invocation.method)
            .put("class", GuidedPublicationReplayIT.class.getName())
            .put("displayLabel", invocation.displayLabel)
            .put("phase", phase)
            .put("variant", invocation.variant)
            .put("invocationOrdinal", invocation.ordinal)
            .put("variantOrdinal", invocation.variantOrdinal)
            .put("diagnosticFailures", MODEL_BUDGET_WITNESS_FAILURES.get());
    var calls = out.putArray("calls");
    MODEL_RESPONSE_FACTS.stream()
        .filter(row -> row.path("invocationOrdinal").asInt() == invocation.ordinal)
        .forEach(
            row -> {
              synchronized (row) {
                calls.add(row.deepCopy());
              }
            });
    var maxima = out.putObject("actualAppliedResponseMaxUtf8Bytes");
    for (String kind : List.of("SOURCE_PLAN", "NEXT_ACTION", "VERIFY_STEP")) {
      long maximum = 0, count = 0;
      for (JsonNode row : calls) {
        if (row.path("kind").asText().equals(kind)
            && row.path("attemptApplied").asBoolean()
            && row.path("textEncoded").asBoolean()) {
          count++;
          maximum = Math.max(maximum, row.path("textUtf8Bytes").asLong());
        }
      }
      maxima.putObject(kind).put("count", count).put("maximum", maximum);
    }
    privateImmutableJson(
        COHORT_DIRECTORY.resolve("responses-" + invocation.key + "-" + phase + ".json"), out);
  }

  private static String exactByteHash(byte[] bytes) {
    try {
      return HexFormat.of()
          .formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));
    } catch (java.security.NoSuchAlgorithmException impossible) {
      throw new IllegalStateException(impossible);
    }
  }

  private static void joinProviderFacts(ObjectNode facts, JsonNode request, JsonNode wire) {
    try {
      ModelCallKey key =
          new ModelCallKey(
              request.path("context").path("sessionId").asText(),
              request.path("requestId").asText(),
              request.path("attempt").asInt());
      ModelCallJoin join = MODEL_CALL_JOINS.get(key);
      if (join == null) {
        throw new IllegalStateException("Missing committed provider attempt join");
      }
      assertThat(request.path("kind").asText()).isEqualTo(join.kind());
      if (MODEL_RESPONSE_JOINS.putIfAbsent(key, facts) != null) {
        throw new IllegalStateException("Duplicate provider response attempt diagnostic join");
      }
      synchronized (facts) {
        facts
            .put("joined", true)
            .put("lane", FIXTURE_PROFILE.lane)
            .put("invocationOrdinal", join.invocation().ordinal)
            .put("variantOrdinal", join.invocation().variantOrdinal)
            .put("sessionOrdinal", join.sessionOrdinal())
            .put("attemptOrdinal", join.attemptOrdinal())
            .put("kind", join.kind())
            .put("persistedInputCeiling", join.inputCeiling())
            .put("requestedOutputCeiling", join.outputCeiling())
            .put(
                "actualWireOutputCeiling",
                wire.path("generationConfig").path("maxOutputTokens").asInt())
            .put("responseTextByteBound", join.responseBound());
      }
    } catch (Exception | AssertionError diagnosticFailure) {
      MODEL_BUDGET_WITNESS_FAILURES.incrementAndGet();
      synchronized (facts) {
        facts.put("instrumentationError", true);
      }
    }
  }

  private void refreshActualResponseDispositions() {
    for (var entry : MODEL_RESPONSE_JOINS.entrySet()) {
      ModelCallJoin join = MODEL_CALL_JOINS.get(entry.getKey());
      String status =
          jdbc.queryForObject(
              "SELECT status FROM studio_guided_model_attempts"
                  + " WHERE session_id=? AND request_id=? AND attempt_number=?",
              String.class,
              join.sessionId(),
              entry.getKey().requestId(),
              entry.getKey().attempt());
      synchronized (entry.getValue()) {
        entry
            .getValue()
            .put("attemptDispositionRead", true)
            .put("attemptApplied", "APPLIED".equals(status));
      }
    }
  }

  private static void assertProviderFactsComplete() {
    assertThat(MODEL_BUDGET_WITNESS_FAILURES.get()).isZero();
    assertThat(MODEL_RESPONSE_FACTS.size()).isEqualTo(MODEL_WIRE.size());
    var seen = new java.util.HashSet<String>();
    for (ObjectNode facts : MODEL_RESPONSE_FACTS) {
      synchronized (facts) {
        assertThat(facts.path("joined").asBoolean()).isTrue();
        assertThat(
                COMMITTED_MODEL_BUDGET_WITNESSES.stream()
                    .filter(
                        witness ->
                            witness.path("sessionOrdinal").asLong()
                                    == facts.path("sessionOrdinal").asLong()
                                && witness.path("attemptOrdinal").asLong()
                                    == facts.path("attemptOrdinal").asLong())
                    .count())
            .as("sent call joins exactly one actual committed pre-send reservation")
            .isEqualTo(1);
        assertDeclaredFixtureCeiling(facts.path("requestedOutputCeiling").asLong());
        assertDeclaredFixtureCeiling(facts.path("actualWireOutputCeiling").asLong());
        assertThat(facts.path("requestUtf8Bytes").asLong())
            .isLessThanOrEqualTo(facts.path("persistedInputCeiling").asLong());
        String key =
            facts.path("invocationOrdinal").asInt()
                + ":"
                + facts.path("sessionOrdinal").asLong()
                + ":"
                + facts.path("attemptOrdinal").asLong();
        assertThat(seen.add(key))
            .as("each actual sent attempt has one response/failure record")
            .isTrue();
        assertThat(facts.path("terminalRecorded").asBoolean()).isTrue();
        assertThat(facts.path("attemptDispositionRead").asBoolean()).isTrue();
        if (facts.path("textEncoded").asBoolean()) {
          assertThat(facts.path("textUtf8Bytes").asLong())
              .isLessThanOrEqualTo(facts.path("responseTextByteBound").asLong());
          assertThat(facts.path("declaredInputUsage").asInt()).isEqualTo(20);
          assertThat(facts.path("declaredOutputUsage").asInt()).isEqualTo(40);
        }
      }
    }
  }

  /**
   * STUDIO-OBS-014 AC-10 canary (ruling AR-2 e): every Studio audit event this class's real guided
   * and replay runs emit, captured from the audit logger itself. The OBS-007 secret-login case
   * registers its canaries in {@link #AUDIT_CANARIES}; {@code
   * auditStreamCarriesIdsAndCodesOnlyAcrossTheWholeClass} asserts none of them appears.
   */
  private static final ch.qos.logback.core.read.ListAppender<
          ch.qos.logback.classic.spi.ILoggingEvent>
      AUDIT_EVENTS = auditCapture();

  private static final java.util.Set<String> AUDIT_CANARIES =
      java.util.concurrent.ConcurrentHashMap.newKeySet();

  private static ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent>
      auditCapture() {
    var appender =
        new ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent>();
    appender.setName("AUDIT_EVENTS");
    return appender;
  }

  /**
   * (Re-)attaches {@link #AUDIT_EVENTS} to the audit logger. Spring Boot stops and resets logback
   * whenever an application context starts (this class's own and each nested replica), which
   * detaches and stops every appender and also drops logback context listeners; so the capture is
   * re-attached after each context start: before every test and right after each nested replica
   * starts (S3b: an attach-once capture stayed empty for the whole class).
   */
  static void ensureAuditCapture() {
    var logger =
        ((ch.qos.logback.classic.LoggerContext) org.slf4j.LoggerFactory.getILoggerFactory())
            .getLogger(com.citi.put.checks.studio.guided.audit.StudioActionAudit.CATEGORY);
    if (!AUDIT_EVENTS.isStarted()) {
      AUDIT_EVENTS.start();
    }
    if (logger.getAppender(AUDIT_EVENTS.getName()) != AUDIT_EVENTS) {
      logger.addAppender(AUDIT_EVENTS);
    }
  }

  private java.util.Set<String> tallyBefore = java.util.Set.of();
  private int tallyAuditStart;

  @org.junit.jupiter.api.AfterAll
  void detachAuditCapture() throws Exception {
    var failures = new ArrayList<Throwable>();
    try {
      p3AttemptTeardown(failures, this::stop);
      if (!finalScansAttempted) {
        p3AttemptTeardown(failures, () -> scanFinalOwnedSinks(false));
      }
      // Context destruction has finished: include any late audit writes before final detachment.
      p3AttemptTeardown(failures, this::scanFinalAuditBoundary);
    } finally {
      // Always retain the genuine partial tally/cohort before any later JVM can overwrite it.
      p3AttemptTeardown(failures, this::retainFinalCohort);
      ((ch.qos.logback.classic.LoggerContext) org.slf4j.LoggerFactory.getILoggerFactory())
          .getLogger(com.citi.put.checks.studio.guided.audit.StudioActionAudit.CATEGORY)
          .detachAppender(AUDIT_EVENTS);
    }
    throwTeardownFailures(failures);
  }

