  private static java.util.Map<String, Long> itrExpectedInvocationMultiset() {
    var expected = new java.util.TreeMap<String, Long>();
    for (String method : SINGLETON_METHODS) {
      if (INCREMENTAL_METHODS.contains(method)
          == (FIXTURE_PROFILE == FixtureProfile.INCREMENTAL_2048)) {
        expected.put(method + "/singleton/0", 1L);
      }
    }
    if (FIXTURE_PROFILE == FixtureProfile.INCREMENTAL_2048) {
      for (int ordinal = 0; ordinal < INCREMENTAL_VARIANTS.size(); ordinal++) {
        expected.put(
            "incrementalStructuralEditsAndExplicitRelearningUseTheActualJoinedBrowser/"
                + INCREMENTAL_VARIANTS.get(ordinal)
                + "/"
                + (ordinal + 1),
            1L);
      }
    }
    return expected;
  }

  private static boolean itrExactWholeLaneObserved() {
    var actual =
        FIXTURE_INVOCATIONS.stream()
            .collect(
                java.util.stream.Collectors.groupingBy(
                    invocation ->
                        invocation.method
                            + "/"
                            + invocation.variant
                            + "/"
                            + invocation.variantOrdinal,
                    java.util.TreeMap::new,
                    java.util.stream.Collectors.counting()));
    return actual.equals(itrExpectedInvocationMultiset());
  }

