  // ---- STUDIO-OBS-015 B3b/B3c source01 (b3abc-design01 s1/s3/s4): inactive unless selected ----

  /** Test-only hooks inside {@code incrementalJoined}; null means the original flow, unchanged. */
  private interface B3Hooks {
    default void texts(String variant, List<String> texts) {}

    default void beforeFinalize(B3Parent parent) throws Exception {}

    default void afterFirstOrdinaryReplay(B3Parent parent, JsonNode merged, UUID execution)
        throws Exception {}
  }

  private record B3Parent(
      String id,
      UUID test,
      JsonNode base,
      JsonNode edited,
      ArrayNode steps,
      int boundary,
      String variant) {}

  private record B3Outcome(
      String label, String stage, String code, int readsDelta, String backendLowering) {}

  private static volatile B3Hooks b3Hooks;
  private static volatile boolean b3ReadInsideDriftStep;
  private static volatile B3FirstSuffixHold b3FirstSuffixHold;
  private static volatile B3EvidenceCapture b3EvidenceCapture;

  /** Value-free per-label stage records: session hash, label, stage, code, reader delta only. */
  private static final List<ObjectNode> B3_OUTCOMES = new CopyOnWriteArrayList<>();

  /** B3B-1 (43/61/60/52/31/42): stored base/source/history authority at actual joined parents. */
  @Test
  void incrementalOriginalBaseAndSourceAuthorityRejectEveryStoredSubstitution() throws Exception {
    b3IsolatedCsi();
    var parent = new java.util.concurrent.atomic.AtomicReference<B3Parent>();
    var merged = new java.util.concurrent.atomic.AtomicReference<JsonNode>();
    try {
      b3AliasDeclarationsRefuseAtActualStartWithoutWrites(); // 42 HTTP leg
      b3Hooks =
          new B3Hooks() {
            @Override
            public void beforeFinalize(B3Parent p) throws Exception {
              parent.set(p);
              b3AssertPinnedBaseProofJoinsActualRows(p); // 61 positive joins
              var probe = new B3WriterProbe(p.id(), p.test());
              probe.positive("gen1-positive");
              JsonNode entries = probe.genuine.path("materializationEvidence").path("entries");
              int lastV2 = -1;
              for (int at = 0; at < entries.size(); at++) {
                if (entries.get(at).path("introducedContextRevision").asInt() == 2) {
                  lastV2 = at;
                }
              }
              assertThat(lastV2).as("actual appended version-2 input").isNotNegative();
              final int v2 = lastV2;
              probe.requireStored( // 52 / route 6, multi-version
                  "wrong-private-input-hash-v2",
                  b -> {
                    ObjectNode e =
                        (ObjectNode) b.path("materializationEvidence").path("entries").get(v2);
                    e.put(
                        "inputHash",
                        GuidedContracts.hash(C.object().put("b3", e.path("inputHash").asText())));
                  });
              int prep = b3IssuedAboveBirth(probe.genuine); // precondition, else OPEN
              probe.requireStored( // 52 / route 7
                  "preparation-substitutes-birth-for-actual",
                  b -> {
                    ObjectNode fact = (ObjectNode) b.path("preparations").get(prep);
                    int revision = b3PreparationContextRevision(b, fact);
                    fact.put(
                        "materializationRevision",
                        b.path("materializationEvidence")
                            .path("versions")
                            .get(revision - 1)
                            .path("birthMaterializationRevision")
                            .asInt());
                  });
              probe.requireBackendPure( // 52 full-version cutoff
                  "historical-cutoff-moves-v2-input-into-v1",
                  b ->
                      ((ObjectNode) b.path("materializationEvidence").path("entries").get(v2))
                          .put("introducedContextRevision", 1));
              probe.requireStored( // 60 / route 3
                  "immutable-source-manifest-hash-is-exact",
                  b ->
                      b.put(
                          "sourceManifestHash",
                          GuidedContracts.hash(
                              C.object().put("b3", b.path("sourceManifestHash").asText()))));
              probe.refuse( // 60 / route 1 (joined analogue; stage recorded, not pinned)
                  "immutable-original-source-cannot-be-replaced",
                  b -> {
                    ObjectNode step =
                        (ObjectNode)
                            b.path("snapshotEvidence")
                                .path("current")
                                .path("authoring")
                                .path("steps")
                                .get(3);
                    ObjectNode context =
                        step.has("context")
                            ? (ObjectNode) step.path("context")
                            : step.putObject("context");
                    context
                        .putArray("entries")
                        .addObject()
                        .put("kind", "text")
                        .put("value", "A different complete source");
                  });
              b3AssertMultiVersionReturnedHistoryRefuses(p); // 52 returned-read (no T3 credit)
              probe.positive("gen1-positive-after");
            }

            @Override
            public void afterFirstOrdinaryReplay(B3Parent p, JsonNode receipt, UUID execution)
                throws Exception {
              merged.set(receipt);
              b3AssertFinalizeIsIdempotentAndModelBrowserFree(p, receipt); // 31
            }
          };
      incrementalJoined("append-input");
      b3Hooks = null;
      assertThat(parent.get()).isNotNull();
      assertThat(merged.get()).isNotNull();
      b3OlderEqualHashBaseAndChangedSourceCas(parent.get(), merged.get()); // 43/61/60 gen 2
    } finally {
      b3Hooks = null;
      incrementalTenScenario = false;
      incrementalDomVariant = null;
      Files.writeString(TEMP.resolve("obs015-native-mode.json"), "{}");
      b3RestoreCsi();
      b3RetainOutcomes();
    }
  }

  /** B3B-2 (63/61/72): drift at j1 keeps the full base proof; null/changed/orphans refuse. */
  @Test
  void incrementalNonemptyOriginalPrefixRetainsBaseProofAfterDriftAtOne() throws Exception {
    b3IsolatedCsi();
    var seen = new java.util.concurrent.atomic.AtomicReference<B3Parent>();
    var raw = new java.util.concurrent.atomic.AtomicReference<String>();
    try {
      b3Hooks =
          new B3Hooks() {
            @Override
            public void beforeFinalize(B3Parent p) throws Exception {
              seen.set(p);
              String nav = b3DriftAtOneFacts(p, raw);
              var probe = new B3WriterProbe(p.id(), p.test());
              probe.positive("drift-one-positive");
              probe.requireBackendPure(
                  "base-proof-null",
                  b -> ((ObjectNode) b.path("snapshotEvidence")).putNull("baseProof"));
              probe.requireBackendPure(
                  "changed-program",
                  b -> {
                    ObjectNode incremental = (ObjectNode) b.path("incrementalEvidence");
                    ObjectNode program = (ObjectNode) incremental.path("program");
                    ((ObjectNode) program.path("actions").get(0))
                        .put("operationHash", "0".repeat(64));
                    ((ObjectNode) incremental.path("plan"))
                        .put("prefixProgramHash", GuidedContracts.hash(program));
                  });
              probe.requireBackendPure(
                  "changed-pin",
                  b -> {
                    String forged =
                        GuidedContracts.hash(
                            C.object().put("b3-forged-pin", p.base().path("revisionId").asText()));
                    ((ObjectNode) b.path("snapshotEvidence").path("pinnedBase"))
                        .put("revisionDigest", forged);
                    ObjectNode incremental = (ObjectNode) b.path("incrementalEvidence");
                    ObjectNode program = (ObjectNode) incremental.path("program");
                    program.put("baseRevisionDigest", forged);
                    ((ObjectNode) incremental.path("plan"))
                        .put("prefixProgramHash", GuidedContracts.hash(program));
                  });
              probe.refuse("base-proof-recomputed-source", b -> b3RecomputedBaseSource(b)); // 61
              probe.refuse( // 61 map
                  "base-proof-recomputed-reuse-map",
                  b -> {
                    ObjectNode proof = (ObjectNode) b.path("snapshotEvidence").path("baseProof");
                    ((ObjectNode) proof.path("revision").path("reusedFrom"))
                        .putObject(INCREMENTAL_STEPS.get(0))
                        .put("revisionId", p.base().path("revisionId").asText())
                        .put("stepId", INCREMENTAL_STEPS.get(0));
                  });
              String bound = probe.genuine.path("producers").get(0).path("bindingId").asText();
              probe.refuse( // 72
                  "hidden-successful-read",
                  b -> {
                    ObjectNode hidden = ((ObjectNode) b.path("producers").get(0)).deepCopy();
                    hidden.put("bindingId", raw.get()).put("producerAdmissionId", nav);
                    ((ArrayNode) b.path("producers")).add(hidden);
                  });
              probe.refuse( // 72 / N01
                  "model-only-orphan",
                  b -> {
                    ObjectNode need =
                        ((ObjectNode) b.path("translationPlan").path("needs").get(0)).deepCopy();
                    need.put("needId", "b3-orphan")
                        .put("bindingId", "b3-orphan-binding")
                        .putArray("consumers");
                    ((ArrayNode) b.path("translationPlan").path("needs")).add(need);
                    ObjectNode allocation = ((ObjectNode) b.path("allocations").get(0)).deepCopy();
                    allocation
                        .put("bindingId", "b3-orphan-binding")
                        .put("needId", "b3-orphan")
                        .putArray("consumers");
                    ((ArrayNode) b.path("allocations")).add(allocation);
                  });
              probe.refuseOffered( // 72
                  "raw-id-recycle",
                  (ObjectNode) C.parse(b3Replace(probe.genuine, bound, raw.get())));
              probe.positive("drift-one-positive-after");
            }

            @Override
            public void afterFirstOrdinaryReplay(B3Parent p, JsonNode merged, UUID execution) {
              JsonNode artifact =
                  C.parse(
                      jdbc.queryForObject(
                          "SELECT artifact::text FROM ui_test_revisions WHERE id=?::uuid",
                          String.class,
                          merged.path("revisionId").asText()));
              assertThat(artifact.path("learnedPlan").path("reusedFrom"))
                  .as("drift at j1 reuses zero steps")
                  .isEmpty();
              assertThat(artifact.toString())
                  .as("raw unperformed import never becomes an executable binding")
                  .doesNotContain(raw.get());
              assertThat(artifact.path("learnedPlan").path("bindings")).hasSize(1);
            }
          };
      incrementalJoined("drift-first");
      assertThat(seen.get()).isNotNull();
    } finally {
      b3Hooks = null;
      b3RestoreCsi();
      b3RetainOutcomes();
    }
  }

  /** B3B-3 (73/75/72): one immutable first acceptance; later pair/obligation/edge loss refuses. */
  @Test
  void incrementalFirstSuffixAcceptanceIsOnceAndLaterPairsCannotDisappear() throws Exception {
    b3IsolatedCsi();
    var hold = new B3FirstSuffixHold();
    var seen = new java.util.concurrent.atomic.AtomicReference<B3Parent>();
    b3FirstSuffixHold = hold;
    java.util.concurrent.Future<ObjectNode> race = null;
    try (var watcher = java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()) {
      race = watcher.submit(() -> b3ContendFirstSuffix(hold));
      final java.util.concurrent.Future<ObjectNode> contention = race;
      try {
        b3Hooks =
            new B3Hooks() {
              @Override
              public void beforeFinalize(B3Parent p) throws Exception {
                seen.set(p);
                ObjectNode contended = contention.get(5, java.util.concurrent.TimeUnit.SECONDS);
                assertThat(contended.path("sessionId").asText()).isEqualTo(p.id());
                assertThat(hold.releasedInTime)
                    .as("the held actual call was released inside its bound")
                    .isTrue();
                for (JsonNode contender : contended.path("contenders")) {
                  assertThat(contender.path("status").asInt()).isEqualTo(409);
                  assertThat(contender.path("code").asText())
                      .as("in-flight first suffix refuses a second reservation")
                      .isEqualTo("IDEMPOTENCY_CONFLICT");
                }
                assertThat(contended.path("contenders")).hasSize(2);
                assertThat(contended.path("acceptancesDuringHold").asInt()).isZero();
                assertThat(contended.path("attemptsDelta").asInt()).isZero();
                assertThat(contended.path("wireDelta").asInt()).isZero();
                b3AssertOneImmutableFirstAcceptance(p); // 73 concurrent/duplicate + removals
                b3AssertLaterLossRefuses(p); // 73 later pair deletion / obligation mutation
                b3EdgeMatrix(p); // 75 / 72 edge side
              }
            };
        incrementalJoined("admitted-drift2");
        assertThat(seen.get()).isNotNull();
      } finally {
        b3Hooks = null;
        b3FirstSuffixHold = null;
        hold.release.countDown();
        if (!race.isDone()) {
          race.cancel(true); // never leave the 120 s watcher waiting after an earlier failure
        }
      }
    } finally {
      b3RestoreCsi();
      b3RetainOutcomes();
    }
  }

