  /**
   * B1A-CB-01 (ledger16 {@code IncrementalSessionIT.prefixCallbacksNeverOpenModelReservation}):
   * actual prefix admit/consume/success/observation callbacks and a direct service completeStep
   * keep REPLAYING_PREFIX, and the SOURCE_PLAN, proposal and direct reservation paths refuse before
   * any committed model reservation or gateway call. The first parent is drained by cancellation
   * after its injected completeStep and earns no other credit; the destructive proposal probe runs
   * last in its own second parent (C4 option a).
   */
  @Test
  void incrementalPrefixCallbacksKeepStateAndFenceBothReservations() throws Exception {
    var service =
        ownedApplicationContext.getBean(
            com.citi.put.checks.studio.guided.session.GuidedSessionService.class);
    var controller =
        com.citi.put.checks.studio.guided.session.GuidedInternalIdentityFixture.controller();
    String step = INCREMENTAL_STEPS.get(0);
    var probes = new ArrayList<B1aProbe>();
    String first;
    int models;
    try (var parent = b1aParent(java.util.EnumSet.allOf(B1aPhase.class))) {
      first = parent.id;
      models = MODEL_WIRE.size();
      ObjectNode admit = b1aAwait(parent, B1aPhase.ADMIT);
      JsonNode admitted = admit.path("stored").path("step0Actions").get(0);
      String navigation = admitted.path("admissionId").asText();
      assertThat(admitted.path("state").asText()).isEqualTo("ADMITTED");
      assertThat(admitted.path("dispatchCount").asInt(-1)).isZero();
      assertThat(admit.path("result").path("admissionId").asText()).isEqualTo(navigation);
      assertThat(admit.path("stored").path("step0Obligations")).hasSize(1);
      JsonNode obligation = admit.path("stored").path("step0Obligations").get(0);
      assertThat(obligation.path("ordinal").asInt(-1)).isZero();
      assertThat(obligation.path("admissionId").asText()).isEqualTo(navigation);
      assertThat(obligation.path("proposalDigest").asText())
          .isEqualTo(admitted.path("requestDigest").asText());
      int proofs = 0;
      for (JsonNode preparation : admit.path("stored").path("preparations")) {
        assertThat(preparation.path("admissionId").asText()).isEqualTo(navigation);
        if (preparation
            .path("preparationId")
            .asText()
            .equals(admitted.path("preparationId").asText())) {
          proofs++;
        }
      }
      assertThat(proofs).as("the sole admission joins its actual preparation proof").isEqualTo(1);
      assertThat(admitted.path("operationHash").asText()).matches("[a-f0-9]{64}");
      assertThat(admitted.path("contextRevision"))
          .isEqualTo(admit.path("stored").path("contextRevision"));
      assertThat(admitted.path("authoredInputsHash").asText())
          .isEqualTo(admit.path("stored").path("authoredInputsHash").asText());
      probes.add(b1aFenceProbes(parent, B1aPhase.ADMIT));
      b1aRelease(parent, B1aPhase.ADMIT);

      ObjectNode consume = b1aAwait(parent, B1aPhase.CONSUME);
      assertThat(consume.path("resultType").asText()).isEqualTo("WonConsumption");
      assertThat(consume.path("result").path("admissionId").asText()).isEqualTo(navigation);
      assertThat(consume.path("result").path("state").asText()).isEqualTo("DISPATCHING");
      JsonNode dispatching = consume.path("stored").path("step0Actions").get(0);
      assertThat(dispatching.path("admissionId").asText()).isEqualTo(navigation);
      assertThat(dispatching.path("state").asText()).isEqualTo("DISPATCHING");
      assertThat(dispatching.path("dispatchCount").asInt(-1)).isEqualTo(1);
      assertThat(consume.path("stored").path("consumeCommands").asInt(-1)).isEqualTo(1);
      probes.add(b1aFenceProbes(parent, B1aPhase.CONSUME));
      b1aRelease(parent, B1aPhase.CONSUME);

      ObjectNode navigated = b1aAwait(parent, B1aPhase.NAVIGATION_SUCCESS);
      JsonNode succeeded = navigated.path("stored").path("step0Actions").get(0);
      assertThat(succeeded.path("admissionId").asText()).isEqualTo(navigation);
      assertThat(b1aSucceeded(succeeded)).isTrue();
      probes.add(b1aFenceProbes(parent, B1aPhase.NAVIGATION_SUCCESS));
      b1aRelease(parent, B1aPhase.NAVIGATION_SUCCESS);

      ObjectNode observed = b1aAwait(parent, B1aPhase.OBSERVATION);
      assertThat(observed.path("stored").path("generation").asLong())
          .isGreaterThan(navigated.path("stored").path("generation").asLong());
      assertThat(observed.path("stored").path("evidenceHash"))
          .isNotEqualTo(navigated.path("stored").path("evidenceHash"));
      assertThat(observed.path("stored").path("observationCommands").asInt())
          .isEqualTo(navigated.path("stored").path("observationCommands").asInt() + 1);
      b1aAssertReadUnperformed(observed.path("stored"), navigation);
      probes.add(b1aFenceProbes(parent, B1aPhase.OBSERVATION));
      // C6: navigation alone passes the UNKNOWN_OUTCOME gate; the installed verifier refuses.
      assertThatThrownBy(
              () ->
                  service.completeStep(
                      controller,
                      parent.id,
                      parent.fence(),
                      "b1a-complete-early-" + UUID.randomUUID(),
                      C.object().put("stepId", step)))
          .isInstanceOf(GuidedSessionException.class)
          .hasMessage("RUNTIME_INCOMPATIBLE");
      assertThat(b1aStoredFacts(jdbc, parent.id)).isEqualTo(observed.path("stored"));
      b1aRelease(parent, B1aPhase.OBSERVATION);

      ObjectNode read = b1aAwait(parent, B1aPhase.READ_SUCCESS);
      JsonNode actions = read.path("stored").path("step0Actions");
      assertThat(actions).hasSize(2);
      assertThat(actions.get(0).path("admissionId").asText()).isEqualTo(navigation);
      assertThat(b1aSucceeded(actions.get(0))).isTrue();
      String readAdmission = actions.get(1).path("admissionId").asText();
      assertThat(actions.get(1).path("kind").asText()).isEqualTo("read");
      assertThat(b1aSucceeded(actions.get(1))).isTrue();
      assertThat(read.path("stored").path("producers")).hasSize(1);
      assertThat(read.path("stored").path("producers").get(0).path("admissionId").asText())
          .isEqualTo(readAdmission);
      assertThat(read.path("stored").path("materializationRevision").asLong())
          .as("the actual producer insertion bumps materialization metadata")
          .isGreaterThan(observed.path("stored").path("materializationRevision").asLong());
      JsonNode obligations = read.path("stored").path("step0Obligations");
      assertThat(obligations).hasSize(2);
      for (int ordinal = 0; ordinal < 2; ordinal++) {
        assertThat(obligations.get(ordinal).path("admissionId").asText())
            .isEqualTo(actions.get(ordinal).path("admissionId").asText());
        assertThat(obligations.get(ordinal).path("proposalDigest").asText())
            .isEqualTo(actions.get(ordinal).path("requestDigest").asText());
      }
      probes.add(b1aFenceProbes(parent, B1aPhase.READ_SUCCESS));
      // Production never calls completeStep during a prefix; this direct service call is the
      // ledger16 "complete" proof only and is distinguished from the actual worker callbacks.
      JsonNode completed =
          service.completeStep(
              controller,
              parent.id,
              parent.fence(),
              "b1a-complete-" + UUID.randomUUID(),
              C.object().put("stepId", step));
      assertThat(completed.path("state").asText()).isEqualTo("REPLAYING_PREFIX");
      ObjectNode after = b1aStoredFacts(jdbc, parent.id);
      assertThat(after.path("stepIndex").asInt(-1)).isEqualTo(1);
      assertThat(after.path("state").asText()).isEqualTo("REPLAYING_PREFIX");
      assertThat(after.path("continuation").asText()).isEqualTo("REPLAYING_PREFIX");
      assertThat(after.path("prefixPending").asBoolean()).isTrue();
      assertThat(after.path("stepCompleteCommands").asInt(-1)).isEqualTo(1);
      assertThat(after.path("switches").asInt(-1)).isZero();
      assertThat(after.path("modelAttempts").asInt(-1)).isZero();
      assertThat(after.path("step0Actions")).isEqualTo(actions);
      // C7: the injected progression is drained by cancellation before the held ACK returns.
      parent.cancel();
      b1aRelease(parent, B1aPhase.READ_SUCCESS);
    }
    assertThat(sessions.transaction(() -> sessions.lock(first).document().path("state").asText()))
        .isEqualTo("CANCELLED");
    assertThat(
            jdbc.queryForObject(
                "SELECT count(*) FROM studio_guided_relearn_switches WHERE session_id=?",
                Integer.class,
                first))
        .isZero();
    assertThat(
            jdbc.queryForObject(
                "SELECT count(*) FROM studio_guided_publications WHERE session_id=?",
                Integer.class,
                first))
        .isZero();
    assertThat(
            jdbc.queryForObject(
                "SELECT count(*) FROM studio_guided_model_attempts WHERE session_id=?",
                Integer.class,
                first))
        .isZero();
    assertThat(MODEL_WIRE).hasSize(models);

    String second;
    int effects;
    int navigations;
    int values;
    long nativeEvents;
    try (var parent = b1aParent(java.util.EnumSet.of(B1aPhase.OBSERVATION))) {
      second = parent.id;
      ObjectNode observed = b1aAwait(parent, B1aPhase.OBSERVATION);
      String navigation =
          observed.path("stored").path("step0Actions").get(0).path("admissionId").asText();
      boolean verified =
          sessions.transaction(
              () -> {
                var locked = sessions.lock(parent.id);
                List<ObjectNode> current =
                    sessions.effectiveActions(parent.id).stream()
                        .filter(
                            action ->
                                action.path("coordinate").path("stepId").asText().equals(step))
                        .toList();
                return new com.citi.put.checks.studio.guided.translation.GuidedStepVerifier(plans)
                    .complete(locked.document(), C.object().put("stepId", step), current);
              });
      assertThat(verified).as("the proposal probe needs an unfinished step").isFalse();
      Map<String, Object> predicates = b1aPredicates(parent.id);
      String accounting = b1aAccounting(parent.id);
      effects = RECEIPTS.size();
      navigations = NAVIGATIONS.get();
      values = VALUES.size();
      nativeEvents = b1aNativeEvents(parent.id);
      int diagnostics = FINALIZE_DIAGNOSTICS.get();
      ObjectNode command = b1aPlanningCommand(parent);
      // C5: re-read immediately before /proposals; an ADMITTED read would enter recover instead.
      b1aAssertReadUnperformed(b1aStoredFacts(jdbc, parent.id), navigation);
      JsonNode refused =
          incrementalControllerProbe(parent.id, parent.fence(), command, 409, "proposals");
      assertThat(refused.path("code").asText()).isEqualTo("REVISION_CONFLICT");
      b1aRouteDiagnostic(
          diagnostics,
          "REVISION_CONFLICT",
          List.of(
              B1A_TRANSLATION + "GuidedTranslationStore#reserveAttempt",
              B1A_TRANSLATION + "GuidedTranslationService#lambda$call$"));
      JsonNode failed = sessions.transaction(() -> sessions.lock(parent.id).progress().deepCopy());
      assertThat(failed.path("errorCode").asText()).isEqualTo("REVISION_CONFLICT");
      assertThat(b1aStoredFacts(jdbc, parent.id).path("state").asText()).isEqualTo("FAILED");
      assertThat(b1aAccounting(parent.id))
          .as("the CSI charge and attempt reservation rolled back; no gateway/provider call")
          .isEqualTo(accounting);
      assertThat(RECEIPTS).hasSize(effects);
      assertThat(NAVIGATIONS.get()).isEqualTo(navigations);
      assertThat(VALUES).hasSize(values);
      assertThat(b1aNativeEvents(parent.id)).isEqualTo(nativeEvents);
      probes.add(
          new B1aProbe(
              B1aPhase.OBSERVATION,
              "proposals",
              Boolean.TRUE.equals(predicates.get("prefix")),
              Boolean.TRUE.equals(predicates.get("delivery"))));
      b1aRelease(parent, B1aPhase.OBSERVATION);
    }
    assertThat(sessions.transaction(() -> sessions.lock(second).document().path("state").asText()))
        .isEqualTo("FAILED");
    assertThat(RECEIPTS).hasSize(effects);
    assertThat(NAVIGATIONS.get()).isEqualTo(navigations);
    assertThat(VALUES).hasSize(values);
    assertThat(b1aNativeEvents(second)).isEqualTo(nativeEvents);
    // C2: reserveAttempt also refuses on delivery-pending; only prefix=true/delivery=false credits.
    assertThat(probes).allMatch(B1aProbe::prefixPending);
    assertThat(probes).anyMatch(B1aProbe::credited);
  }

  // ---------------------------------------------------------------------------------------------
  // STUDIO-OBS-015 B1b/B1c/B1d (b1bcd-design01, with qa-d1-review01 D1/F2/F3 and
  // qa-source-review02 R3 applied). Eleven low-lane singletons and their test-only instruments.
  // Every instrument is inactive unless a B1 parent arms it; a held request or commit continues
  // byte-identically on release. No clock, lease, policy, timeout or production value is changed.
  // ---------------------------------------------------------------------------------------------

  /**
   * B1B-01 (ledger 20 resume; OPEN matrix rows SUCCEEDED-restart, ADMITTED, DISPATCHING): a
   * replacement coordinator resumes at the next unconsumed prefix coordinate, re-dispatches an
   * existing ADMITTED admission once, and marks an existing DISPATCHING admission UNKNOWN without a
   * resend.
   */
  @Test
  void incrementalPrefixRecoveryUsesNextUnconsumedCoordinate() throws Exception {
    // R1: restart between continuations.
    try (var parent = b1Parent(new B1Spec().edit4())) {
      var cut = B1Cut.arm(B1Cut.Kind.PLANS_ENTRY, parent.id, null, 3);
      assertThat(cut.entered.await(45, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
      assertThat(cut.failure).isNull();
      JsonNode program = sessions.transaction(() -> sessions.incremental().program(parent.id));
      JsonNode expected = sessions.transaction(() -> sessions.incremental().nextAction(parent.id));
      assertThat(expected)
          .as("the held continuation is the only one; the next coordinate is unambiguous")
          .isNotNull();
      assertThat(
              jdbc.queryForObject(
                  "SELECT count(*) FROM studio_guided_actions WHERE session_id=?"
                      + " AND document->>'state'='SUCCEEDED'",
                  Integer.class,
                  parent.id))
          .as("a non-trivial restart point")
          .isPositive();
      assertThat(
              jdbc.queryForObject(
                  "SELECT count(*) FROM studio_guided_actions WHERE session_id=?"
                      + " AND document->>'state' IN ('ADMITTED','DISPATCHING')",
                  Integer.class,
                  parent.id))
          .isZero();
      String before =
          jdbc.queryForObject(
              "SELECT jsonb_agg(to_jsonb(a) ORDER BY step_id,ordinal,attempt_ordinal)::text"
                  + " FROM studio_guided_actions a WHERE session_id=?",
              String.class,
              parent.id);
      int requests = b1Count("studio_guided_prefix_requests", parent.id);
      int model = MODEL_WIRE.size();
      int legacy = LEGACY_MODEL_CALLS.get();
      b1ReplacementContinue();
      var added =
          sessions.transaction(() -> sessions.actions(parent.id)).stream()
              .filter(a -> !before.contains(a.path("admission").path("admissionId").asText()))
              .toList();
      assertThat(added).hasSize(1);
      assertThat(added.getFirst().path("coordinate")).isEqualTo(expected.path("coordinate"));
      assertThat(added.getFirst().path("state").asText()).isEqualTo("SUCCEEDED");
      assertThat(added.getFirst().path("dispatchCount").asInt()).isEqualTo(1);
      assertThat(added.getFirst().path("attemptOrdinal").asInt()).isZero();
      assertThat(
              jdbc.queryForObject(
                  "SELECT jsonb_agg(to_jsonb(a) ORDER BY step_id,ordinal,attempt_ordinal)::text"
                      + " FROM studio_guided_actions a WHERE session_id=? AND admission_id<>?",
                  String.class,
                  parent.id,
                  added.getFirst().path("admission").path("admissionId").asText()))
          .as("earlier coordinates are never re-dispatched or rewritten")
          .isEqualTo(before);
      assertThat(b1Count("studio_guided_prefix_requests", parent.id)).isEqualTo(requests + 1);
      assertThat(MODEL_WIRE).hasSize(model);
      assertThat(LEGACY_MODEL_CALLS.get()).isEqualTo(legacy);
      cut.release.countDown();
      b1AwaitRow(
          "SELECT count(*) FROM studio_guided_relearn_switches WHERE session_id=?",
          parent.id,
          Duration.ofSeconds(60));
      for (JsonNode action : program.path("actions")) {
        var same =
            sessions.transaction(() -> sessions.actions(parent.id)).stream()
                .filter(a -> a.path("coordinate").equals(action.path("coordinate")))
                .toList();
        assertThat(same).hasSize(1);
        assertThat(same.getFirst().path("state").asText()).isEqualTo("SUCCEEDED");
        assertThat(same.getFirst().path("dispatchCount").asInt()).isEqualTo(1);
        assertThat(same.getFirst().path("operationHash")).isEqualTo(action.path("operationHash"));
      }
      assertThat(
              sessions.transaction(() -> sessions.actions(parent.id)).stream()
                  .map(a -> a.path("executionEvidence").path("contextId").asText())
                  .distinct()
                  .toList())
          .hasSize(1);
      assertThat(cut.failure).isNull();
    }
    // R2: existing ADMITTED. The real admit committed; consume has not been entered.
    try (var parent = b1Parent(new B1Spec().edit4().nativeMode("b1b-recover", 1, 0))) {
      var cut = B1Cut.arm(B1Cut.Kind.ADMIT_COMMIT, parent.id, b1Coordinate(1, 0), 0);
      assertThat(cut.entered.await(45, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
      assertThat(cut.failure).isNull();
      String admission = cut.admissionId;
      JsonNode admitted = b1Action(parent.id, admission);
      assertThat(admitted.path("state").asText()).isEqualTo("ADMITTED");
      assertThat(admitted.path("dispatchCount").asInt()).isZero();
      assertThat(
              b1Native(parent.id).stream()
                  .filter(e -> e.path("admissionId").asText().equals(admission))
                  .toList())
          .isEmpty();
      int effects = RECEIPTS.size();
      b1ReplacementContinue(); // recovery: advancePrefix existing ADMITTED -> dispatch.dispatch
      JsonNode recovered = b1Action(parent.id, admission);
      assertThat(recovered.path("state").asText()).isEqualTo("SUCCEEDED");
      assertThat(recovered.path("dispatchCount").asInt()).isEqualTo(1);
      assertThat(b1NativeCount(parent.id, admission, "NATIVE_COMPLETED")).isEqualTo(1);
      String consumeKey = "prefix-dispatch-" + recovered.path("idempotencyKey").asText();
      assertThat(b1ConsumeCommands(parent.id, consumeKey)).isEqualTo(1);
      cut.release.countDown(); // the original sender: same key/digest, no second runner send
      long end = System.nanoTime() + Duration.ofSeconds(20).toNanos();

      // IT-R POLL 23: exact original transitions; one old interval owed at most.
      final var itrRead023End = end;
      class ItrState023 {
        boolean firstIteration = true;
        boolean terminal;
        boolean intervalOwed;
        long owedUntil;
        Exception firstException;
        Error firstError;
      }
      final var itr023 = new ItrState023();

      java.util.concurrent.Callable<Boolean> itrPoll023 =
          () -> {
            if (itr023.firstException != null) {
              throw itr023.firstException;
            }
            if (itr023.firstError != null) {
              throw itr023.firstError;
            }
            if (itr023.terminal) {
              return true;
            }
            try {
              if (itr023.intervalOwed) {
                if (Thread.interrupted()) {
                  throw new InterruptedException();
                }
                if (System.nanoTime() < itr023.owedUntil) {
                  return false;
                }
                itr023.intervalOwed = false;
              }
              if (!(b1Count("studio_guided_relearn_switches", parent.id) == 0
                  && System.nanoTime() < itrRead023End)) {
                itr023.terminal = true;
                return true;
              }
              itr023.firstIteration = false;
              itr023.intervalOwed = true;
              itr023.owedUntil = System.nanoTime() + Duration.ofMillis(20).toNanos();
              return false;
            } catch (Exception itrFailure023) {
              if (itr023.firstException == null && itr023.firstError == null) {
                itr023.firstException = itrFailure023;
                itr023.terminal = true;
              }
              throw itr023.firstException;
            } catch (Error itrFailure023) {
              if (itr023.firstException == null && itr023.firstError == null) {
                itr023.firstError = itrFailure023;
                itr023.terminal = true;
              }
              throw itr023.firstError;
            }
          };
      try {
        while (!itr023.terminal) {
          // First invocation is manual. Reentry serves only the original pending transition.
          boolean itrDone023 = itrPoll023.call();
          if (itrDone023) {
            break;
          }
          if (Thread.interrupted()) {
            throw new InterruptedException();
          }
          long itrNow023 = System.nanoTime();
          long itrRemaining023 = itrRead023End - itrNow023;
          long itrOwed023 = itr023.intervalOwed ? itr023.owedUntil - itrNow023 : 0;
          // Semantic deadline is unchanged. Only the already-entered old interval may extend this
          // bound.
          long itrBound023 = Math.max(itrRemaining023, itrOwed023);
          if (itrBound023 > 0) {
            final boolean[] itrFirstTick023 = {true};
            try {
              org.awaitility.Awaitility.await("ReplayIT POLL 23")
                  .atMost(Duration.ofNanos(itrBound023))
                  .pollInterval(Duration.ofMillis(20))
                  .pollDelay(Duration.ZERO)
                  .pollInSameThread()
                  .dontCatchUncaughtExceptions()
                  .ignoreNoExceptions()
                  .until(
                      () -> {
                        try {
                          if (itr023.firstException != null) {
                            throw itr023.firstException;
                          }
                          if (itr023.firstError != null) {
                            throw itr023.firstError;
                          }
                          if (itr023.terminal) {
                            return true;
                          }
                          if (Thread.interrupted()) {
                            throw new InterruptedException();
                          }
                          if (itrFirstTick023[0]) {
                            itrFirstTick023[0] = false;
                            return false; // Cached tick: no second immediate
                            // condition/read/effect.
                          }
                          boolean itrObserved023 = itrPoll023.call();
                          if (!itrObserved023 && Thread.interrupted()) {
                            throw new InterruptedException();
                          }
                          return itrObserved023;
                        } catch (Exception itrFailure023) {
                          if (itr023.firstException == null && itr023.firstError == null) {
                            itr023.firstException = itrFailure023;
                            itr023.terminal = true;
                          }
                          if (itr023.firstError != null) {
                            throw itr023.firstError;
                          }
                          throw itr023.firstException;
                        } catch (Error itrFailure023) {
                          if (itr023.firstException == null && itr023.firstError == null) {
                            itr023.firstError = itrFailure023;
                            itr023.terminal = true;
                          }
                          if (itr023.firstException != null) {
                            throw itr023.firstException;
                          }
                          throw itr023.firstError;
                        }
                      });
            } catch (org.awaitility.core.ConditionTimeoutException itrTimeout023) {
              if (itr023.firstException != null) {
                throw itr023.firstException;
              }
              if (itr023.firstError != null) {
                throw itr023.firstError;
              }
              // A late terminal outcome wins. Otherwise next driver step preserves old guard/body
              // order.
            }
          }
          // Includes bound<=0/no-Await: no silent pending exit, synthetic timeout, or terminal
          // replay.
        }
      } catch (Exception itrFailure023) {
        if (itr023.firstException == null && itr023.firstError == null) {
          itr023.firstException = itrFailure023;
          itr023.terminal = true;
        }
        if (itr023.firstError != null) {
          throw itr023.firstError;
        }
        throw itr023.firstException;
      } catch (Error itrFailure023) {
        if (itr023.firstException == null && itr023.firstError == null) {
          itr023.firstError = itrFailure023;
          itr023.terminal = true;
        }
        if (itr023.firstException != null) {
          throw itr023.firstException;
        }
        throw itr023.firstError;
      } finally {

      }

      assertThat(b1NativeCount(parent.id, admission, "NATIVE_COMPLETED")).isEqualTo(1);
      assertThat(b1NativeCount(parent.id, admission, "DISPATCH_ENTER")).isEqualTo(1);
      assertThat(b1ConsumeCommands(parent.id, consumeKey)).isEqualTo(1);
      assertThat(b1AttemptOneActions(parent.id)).isZero();
      assertThat(RECEIPTS.size()).as("a fill is not a submit").isEqualTo(effects);
      assertThat(cut.failure).isNull();
    }
    // R3: existing DISPATCHING. The real consume committed; the transport send has not started.
    try (var parent = b1Parent(new B1Spec().edit4().nativeMode("b1b-recover", 1, 0))) {
      var cut = B1Cut.arm(B1Cut.Kind.CONSUME_COMMIT, parent.id, b1Coordinate(1, 0), 0);
      assertThat(cut.entered.await(45, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
      assertThat(cut.failure).isNull();
      String admission = cut.admissionId;
      assertThat(cut.ledgerState).isEqualTo("DISPATCHING");
      b1ReplacementContinue(); // recovery: advancePrefix existing DISPATCHING -> lostAcknowledgment
      assertThat(parent.state()).isEqualTo("UNKNOWN_OUTCOME");
      p3AwaitTeardown(parent.id); // the runtime stops before the single held capability returns
      cut.release.countDown();
      Thread.sleep(2000); // bounded wait for the original sender to reach its refused transport
      JsonNode action = b1Action(parent.id, admission);
      assertThat(action.path("state").asText()).isEqualTo("UNKNOWN_OUTCOME");
      assertThat(action.path("outcomeCode").asText()).isEqualTo("ACK_LOST");
      assertThat(action.path("dispatchCount").asInt()).isEqualTo(1);
      assertThat(
              b1Native(parent.id).stream()
                  .filter(
                      e ->
                          e.path("admissionId").asText().equals(admission)
                              && e.path("phase").asText().startsWith("NATIVE_"))
                  .toList())
          .as("no native effect and no resend")
          .isEmpty();
      assertThat(
              jdbc.queryForObject(
                  "SELECT count(*) FROM studio_guided_commands WHERE namespace=?"
                      + " AND route='v2-consume'",
                  Integer.class,
                  parent.id))
          .isEqualTo(
              jdbc.queryForObject(
                  "SELECT count(*) FROM studio_guided_actions WHERE session_id=?"
                      + " AND (document->>'dispatchCount')::int=1",
                  Integer.class,
                  parent.id));
      assertThat(b1AttemptOneActions(parent.id)).isZero();
      assertThat(b1Count("studio_guided_model_attempts", parent.id)).isZero();
    }
  }

  /**
   * B1B-02 (ledger 20 concurrent duplicate transition): four exact byte duplicates of the runner's
   * authentic PRE_ADMISSION receipt, then the runner's own callback, commit exactly one receipt,
   * one DRIFT switch and one SOURCE_PLAN reservation, with no repeated dispatch.
   */
  @Test
  void incrementalConcurrentAuthenticatedDriftCommitsOneSwitch() throws Exception {
    try (var parent =
        b1Parent(
            new B1Spec().edit4().mixedDom("drift-auth-pre").nativeMode("drift-auth-pre", 1, 0))) {
      ObjectNode authentic = b1AwaitDriftCapture(parent.id);
      assertThat(authentic.path("receipt").path("phase").asText()).isEqualTo("PRE_ADMISSION");
      String prefixBefore = b1ActionsAt(parent.id, 0, 0) + b1ActionsAt(parent.id, 0, 1);
      long fence = authentic.path("receipt").path("ownerFence").asLong();
      String worker = token("owning-worker", "worker-1", "studio-guided-controller");
      var go = new java.util.concurrent.CountDownLatch(1);
      try (var pool = java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()) {
        var replies = new ArrayList<java.util.concurrent.Future<HttpResponse<String>>>();
        for (int i = 0; i < 4; i++) {
          replies.add(
              pool.submit(
                  () -> {
                    go.await();
                    return incrementalDriftProbe(parent.id, fence, authentic, worker, TLS);
                  }));
        }
        go.countDown();
        for (var reply : replies) {
          assertThat(reply.get(20, java.util.concurrent.TimeUnit.SECONDS).statusCode())
              .isEqualTo(202);
        }
      }
      INCREMENTAL_ACK_RELEASE.get(parent.id).countDown(); // the runner's own fifth delivery
      awaitFinalizing(parent.id);
      assertThat(b1Count("studio_guided_no_invocation_receipts", parent.id)).isEqualTo(1);
      var switched =
          jdbc.queryForMap(
              "SELECT reason,effective_step_index,next_ordinal,drift_receipt_hash"
                  + " FROM studio_guided_relearn_switches WHERE session_id=?",
              parent.id);
      assertThat(switched.get("reason")).isEqualTo("DRIFT");
      assertThat(((Number) switched.get("effective_step_index")).intValue()).isEqualTo(1);
      assertThat(((Number) switched.get("next_ordinal")).intValue()).isZero();
      assertThat(switched.get("drift_receipt_hash"))
          .isEqualTo(authentic.path("receipt").path("receiptHash").asText());
      assertThat(b1SourcePlanAttempts(parent.id)).isEqualTo(1);
      assertThat(
              jdbc.queryForObject(
                  "SELECT count(DISTINCT request_id) FROM studio_guided_model_attempts"
                      + " WHERE session_id=? AND kind='SOURCE_PLAN'",
                  Integer.class,
                  parent.id))
          .isEqualTo(1);
      assertThat(b1AttemptsBeforeSwitch(parent.id)).isZero();
      assertThat(b1ActionsAt(parent.id, 0, 0) + b1ActionsAt(parent.id, 0, 1))
          .isEqualTo(prefixBefore);
      var fill =
          sessions.transaction(() -> sessions.actions(parent.id)).stream()
              .filter(a -> a.path("coordinate").equals(b1Coordinate(1, 0)))
              .toList();
      assertThat(fill).hasSize(1);
      assertThat(fill.getFirst().path("attemptOrdinal").asInt()).isZero();
      assertThat(fill.getFirst().path("dispatchCount").asInt()).isEqualTo(1);
      assertThat(
              b1NativeCount(
                  parent.id,
                  fill.getFirst().path("admission").path("admissionId").asText(),
                  "NATIVE_COMPLETED"))
          .isEqualTo(1);
      // openapi readGuidedResult: FINALIZING before /finalize is pending publication = 202.
      JsonNode result =
          publicCall("/api/v1/studio/guided-sessions/" + parent.id + "/result", null, 202, null);
      assertThat(result.path("outcome").asText()).isEqualTo("FINALIZING");
      assertThat(result.path("publication").path("status").asText()).isEqualTo("PENDING");
      assertThat(result.path("relearnedFrom"))
          .isEqualTo(C.object().put("stepId", b1Step(1)).put("driftSwitchStepId", b1Step(1)));
    }
  }

  /**
   * B1B-03 (ledger 48; ledger 54 callback-tier joins; B3 routes 9, 10, 13, 14): every forged
   * transport, contract and identity join of an authentic drift receipt is refused with zero
   * writes; only the runner's own authenticated callback commits; late callbacks are inert or
   * refused; a cancelled session and a naturally expired owner lease refuse the authentic body.
   */
  @Test
  void incrementalDriftAuthorityRejectsEveryExactJoin() throws Exception {
    for (String phase : List.of("ADMITTED", "PRE")) {
      boolean admitted = phase.equals("ADMITTED");
      var spec = new B1Spec().edit4();
      if (admitted) {
        spec.nativeMode("drift-auth", 1, 0);
      } else {
        spec.mixedDom("drift-auth-pre").nativeMode("drift-auth-pre", 1, 0);
      }
      try (var parent = b1Parent(spec)) {
        ObjectNode authentic = b1AwaitDriftCapture(parent.id);
        long started = System.nanoTime();
        assertThat(authentic.path("receipt").path("phase").asText())
            .isEqualTo(admitted ? "ADMITTED_PRE_INVOCATION" : "PRE_ADMISSION");
        long fence = authentic.path("receipt").path("ownerFence").asLong();
        String path = "/internal/v2/studio/guided-sessions/" + parent.id + "/outcomes";
        String foreignPath = "/internal/v2/studio/guided-sessions/" + parent.base + "/outcomes";
        String worker = token("owning-worker", "worker-1", "studio-guided-controller");
        String pending = incrementalPendingSnapshot(parent.id);
        String immutable = incrementalImmutableSnapshot(parent.id);
        int model = MODEL_WIRE.size();
        SSLContext noCertificate = b1NoClientCertificate();
        var rows = new java.util.LinkedHashMap<String, B1Probe>();
        rows.put(
            "no-mtls",
            new B1Probe(authentic, worker, noCertificate, fence, path, 401, "UNAUTHENTICATED"));
        rows.put("no-auth", new B1Probe(authentic, null, TLS, fence, path, 401, "UNAUTHENTICATED"));
        rows.put(
            "alg-hs256",
            new B1Probe(
                authentic,
                b1Token(b1Claims("owning-worker", "worker-1"), "HS256", true),
                TLS,
                fence,
                path,
                401,
                "UNAUTHENTICATED"));
        rows.put(
            "alg-none-sig",
            new B1Probe(
                authentic,
                b1Token(b1Claims("owning-worker", "worker-1"), "none", false),
                TLS,
                fence,
                path,
                401,
                "UNAUTHENTICATED"));
        long now = Instant.now().getEpochSecond();
        rows.put(
            "expired",
            new B1Probe(
                authentic,
                b1Token(
                    b1Claims("owning-worker", "worker-1")
                        .put("iat", now - 400)
                        .put("exp", now - 200),
                    "RS256",
                    true),
                TLS,
                fence,
                path,
                401,
                "UNAUTHENTICATED"));
        rows.put(
            "aud",
            new B1Probe(
                authentic,
                b1Token(
                    b1Claims("owning-worker", "worker-1").put("aud", "studio-runner"),
                    "RS256",
                    true),
                TLS,
                fence,
                path,
                401,
                "UNAUTHENTICATED"));
        rows.put(
            "role-controller",
            new B1Probe(
                authentic,
                token("backend-controller", "controller-1", "studio-guided-controller"),
                TLS,
                fence,
                path,
                403,
                "FORBIDDEN_SCOPE"));
        rows.put(
            "other-worker",
            new B1Probe(
                authentic,
                token("owning-worker", "other-worker", "studio-guided-controller"),
                TLS,
                fence,
                path,
                403,
                "FORBIDDEN_SCOPE"));
        rows.put(
            "fence+1",
            new B1Probe(authentic, worker, TLS, fence + 1, path, 403, "FORBIDDEN_SCOPE"));
        rows.put(
            "cross-session",
            new B1Probe(authentic, worker, TLS, fence, foreignPath, 422, "INVALID_CONTRACT"));
        // B3 routes 9/10/14 (assigned to B1): exact original body; transport/assignment varied
        // only.
        rows.put(
            "alg-hs256-hmac",
            new B1Probe(
                authentic,
                b1HmacConfusionToken(b1Claims("owning-worker", "worker-1")),
                TLS,
                fence,
                path,
                401,
                "UNAUTHENTICATED"));
        rows.put(
            "no-auth-no-cert",
            new B1Probe(authentic, null, noCertificate, fence, path, 401, "UNAUTHENTICATED"));
        rows.put(
            "wrong-assignment-path",
            new B1Probe(authentic, worker, TLS, fence, foreignPath, 422, "INVALID_CONTRACT"));
        ObjectNode otherAssignment = authentic.deepCopy();
        ((ObjectNode) otherAssignment.path("receipt")).put("sessionId", parent.base);
        rows.put(
            "wrong-assignment-receipt",
            new B1Probe(
                b1Rehash(otherAssignment), worker, TLS, fence, path, 422, "INVALID_CONTRACT"));
        var text = JSON.getNodeFactory();
        ObjectNode schema = authentic.deepCopy();
        ((ObjectNode) schema.path("receipt")).put("schemaVersion", 2);
        rows.put(
            "schemaVersion",
            new B1Probe(schema, worker, TLS, fence, path, 409, "RUNTIME_INCOMPATIBLE"));
        ObjectNode claims = authentic.deepCopy();
        claims.set("modelClaims", C.object());
        rows.put(
            "model-claims", new B1Probe(claims, worker, TLS, fence, path, 422, "INVALID_CONTRACT"));
        rows.put(
            "native-started",
            new B1Probe(
                b1Forge(authentic, "nativeInvocationStarted", text.booleanNode(true)),
                worker,
                TLS,
                fence,
                path,
                422,
                "INVALID_CONTRACT"));
        rows.put(
            "attempt1",
            new B1Probe(
                b1Forge(authentic, "attemptOrdinal", text.numberNode(1)),
                worker,
                TLS,
                fence,
                path,
                422,
                "INVALID_CONTRACT"));
        ObjectNode hash = authentic.deepCopy();
        ((ObjectNode) hash.path("receipt")).put("receiptHash", "0".repeat(64));
        rows.put("hash", new B1Probe(hash, worker, TLS, fence, path, 409, "EVIDENCE_MISMATCH"));
        // D1 is fixed (verifyPrefixReceipt binds exactly 11 fields): each bound field is refused
        // by Java with STALE_FENCE before any write.
        var bound = new java.util.LinkedHashMap<String, JsonNode>();
        bound.put("workerId", text.textNode("foreign-worker"));
        bound.put("ownerFence", text.numberNode(fence + 1));
        bound.put("scopeHash", text.textNode("0".repeat(64)));
        bound.put("contextId", text.textNode("foreign-context"));
        bound.put(
            "contextRevision",
            text.numberNode(authentic.path("receipt").path("contextRevision").asInt() + 1));
        bound.put("sourceRevision", text.textNode("999"));
        bound.put("configurationRevision", text.textNode("999"));
        bound.put("authoredInputsHash", text.textNode("0".repeat(64)));
        bound.put("prefixProgramHash", text.textNode("0".repeat(64)));
        for (var field : bound.entrySet()) {
          rows.put(
              "bound-" + field.getKey(),
              new B1Probe(
                  b1Forge(authentic, field.getKey(), field.getValue()),
                  worker,
                  TLS,
                  fence,
                  path,
                  409,
                  "STALE_FENCE"));
        }
        // R3 pin semantics: these three are not Java-bound; only the V21 receipt guard/FK refuses
        // them. The static trace maps that refusal through GuidedInternalController.unexpected to
        // UNKNOWN_OUTCOME. The exact code is pinned; a first-run difference is a finding to rule.
        for (String field : List.of("requestDigest", "operationHash", "evidenceHash")) {
          rows.put(
              "trigger-" + field,
              new B1Probe(
                  b1Forge(authentic, field, text.textNode("0".repeat(64))),
                  worker,
                  TLS,
                  fence,
                  path,
                  409,
                  "UNKNOWN_OUTCOME"));
        }
        String readAdmission =
            jdbc.queryForObject(
                "SELECT admission_id FROM studio_guided_actions WHERE session_id=? AND step_id=?"
                    + " AND ordinal=1",
                String.class,
                parent.id,
                b1Step(0));
        String readPreparation =
            jdbc.queryForObject(
                "SELECT document->>'preparationId' FROM studio_guided_actions"
                    + " WHERE session_id=? AND admission_id=?",
                String.class,
                parent.id,
                readAdmission);
        if (admitted) {
          rows.put(
              "crossed-prep",
              new B1Probe(
                  b1Forge(authentic, "preparationId", text.textNode(readPreparation)),
                  worker,
                  TLS,
                  fence,
                  path,
                  409,
                  "EVIDENCE_MISMATCH"));
          rows.put(
              "crossed-adm",
              new B1Probe(
                  b1Forge(authentic, "admissionId", text.textNode(readAdmission)),
                  worker,
                  TLS,
                  fence,
                  path,
                  409,
                  "IDEMPOTENCY_CONFLICT"));
          ObjectNode succeeded = authentic.deepCopy();
          ((ObjectNode) succeeded.path("ledger"))
              .put("state", "SUCCEEDED")
              .put("outcomeCode", "OK");
          rows.put(
              "ledger-state",
              new B1Probe(succeeded, worker, TLS, fence, path, 409, "EVIDENCE_MISMATCH"));
          ObjectNode nullLedger = authentic.deepCopy();
          nullLedger.putNull("ledger");
          rows.put(
              "null-ledger",
              new B1Probe(nullLedger, worker, TLS, fence, path, 422, "INVALID_CONTRACT"));
        } else {
          ObjectNode withLedger = authentic.deepCopy();
          withLedger.set("ledger", C.object().put("state", "FAILED"));
          rows.put(
              "pre-with-ledger",
              new B1Probe(withLedger, worker, TLS, fence, path, 422, "INVALID_CONTRACT"));
          rows.put(
              "pre-admission-id",
              new B1Probe(
                  b1Forge(authentic, "admissionId", text.textNode(readAdmission)),
                  worker,
                  TLS,
                  fence,
                  path,
                  422,
                  "INVALID_CONTRACT"));
        }
        for (var row : rows.entrySet()) {
          B1Probe probe = row.getValue();
          var reply =
              b1RawOutcome(
                  probe.path(),
                  probe.fence(),
                  probe.body().toString(),
                  probe.bearer(),
                  probe.tls());
          assertThat(reply.statusCode()).as(row.getKey()).isEqualTo(probe.status());
          assertThat(C.parse(reply.body()).path("code").asText())
              .as(row.getKey())
              .isEqualTo(probe.code());
          assertThat(incrementalPendingSnapshot(parent.id)).as(row.getKey()).isEqualTo(pending);
          assertThat(incrementalImmutableSnapshot(parent.id)).as(row.getKey()).isEqualTo(immutable);
        }
        assertThat(b1Count("studio_guided_no_invocation_receipts", parent.id)).isZero();
        assertThat(
                jdbc.queryForObject(
                    "SELECT status FROM studio_guided_prefix_requests WHERE session_id=?"
                        + " AND request_digest=?",
                    String.class,
                    parent.id,
                    authentic.path("receipt").path("requestDigest").asText()))
            .isEqualTo(admitted ? "PREPARED" : "ISSUED");
        assertThat(parent.state()).isEqualTo("REPLAYING_PREFIX");
        assertThat(MODEL_WIRE).hasSize(model);
        assertThat(System.nanoTime() - started)
            .as("released inside the unchanged 15s transport deadline")
            .isLessThan(Duration.ofSeconds(12).toNanos());
        INCREMENTAL_ACK_RELEASE.get(parent.id).countDown(); // positive: the runner's own callback
        b1AwaitRow(
            "SELECT count(*) FROM studio_guided_relearn_switches WHERE session_id=?",
            parent.id,
            Duration.ofSeconds(20));
        assertThat(
                jdbc.queryForObject(
                    "SELECT receipt_hash FROM studio_guided_no_invocation_receipts"
                        + " WHERE session_id=?",
                    String.class,
                    parent.id))
            .isEqualTo(authentic.path("receipt").path("receiptHash").asText());
        assertThat(
                jdbc.queryForObject(
                    "SELECT reason FROM studio_guided_relearn_switches WHERE session_id=?",
                    String.class,
                    parent.id))
            .isEqualTo("DRIFT");
        var identical = b1RawOutcome(path, fence, authentic.toString(), worker, TLS);
        assertThat(identical.statusCode()).as("late identical duplicate is inert").isEqualTo(202);
        var different =
            b1RawOutcome(
                path,
                fence,
                b1Forge(authentic, "reason", text.textNode("LOCATOR_AMBIGUOUS")).toString(),
                worker,
                TLS);
        assertThat(different.statusCode()).isEqualTo(409);
        assertThat(C.parse(different.body()).path("code").asText())
            .isEqualTo("IDEMPOTENCY_CONFLICT");
        assertThat(b1Count("studio_guided_no_invocation_receipts", parent.id)).isEqualTo(1);
        assertThat(b1Count("studio_guided_relearn_switches", parent.id)).isEqualTo(1);
        if (admitted) {
          JsonNode spent = b1SpentAttempt(parent.id);
          assertThat(spent.path("state").asText()).isEqualTo("FAILED");
          assertThat(spent.path("outcomeCode").asText()).isEqualTo("TARGET_CHANGED");
          assertThat(spent.path("dispatchCount").asInt()).isEqualTo(1);
          assertThat(spent.path("preparationId"))
              .isEqualTo(authentic.path("receipt").path("preparationId"));
          assertThat(
                  b1NativeCount(
                      parent.id,
                      spent.path("admission").path("admissionId").asText(),
                      "NATIVE_ENTER"))
              .isZero();
        }
      }
    }
    for (String late : List.of("CANCEL", "EXPIRY")) {
      try (var parent =
          b1Parent(
              new B1Spec().edit4().mixedDom("drift-auth-pre").nativeMode("drift-auth-pre", 1, 0))) {
        ObjectNode authentic = b1AwaitDriftCapture(parent.id);
        long fence = authentic.path("receipt").path("ownerFence").asLong();
        String path = "/internal/v2/studio/guided-sessions/" + parent.id + "/outcomes";
        String expected;
        if (late.equals("CANCEL")) {
          parent.cancel();
          expected = "CANCELLED";
        } else {
          b1StallWorker();
          b1AwaitNaturalLeaseExpiry(parent.id);
          expected = "STALE_FENCE";
        }
        refreshFixtureCredentials();
        var reply =
            b1RawOutcome(
                path,
                fence,
                authentic.toString(),
                token("owning-worker", "worker-1", "studio-guided-controller"),
                TLS);
        assertThat(reply.statusCode()).as(late).isEqualTo(409);
        assertThat(C.parse(reply.body()).path("code").asText()).as(late).isEqualTo(expected);
        b1ResumeWorker();
        INCREMENTAL_ACK_RELEASE.get(parent.id).countDown();
        Thread.sleep(1500);
        assertThat(b1Count("studio_guided_no_invocation_receipts", parent.id)).isZero();
        assertThat(b1Count("studio_guided_relearn_switches", parent.id)).isZero();
        assertThat(b1Count("studio_guided_model_attempts", parent.id)).isZero();
      }
    }
  }

  /**
   * B1B-04 (ledger 54 publication tier): the real publication basis joins exactly one excluded
   * ADMITTED attempt to its committed receipt, and refuses disclosed substituted read copies that
   * change a join, invent a PRE_ADMISSION action or hide another unsettled action.
   */
  @Test
  void incrementalExcludedAttemptCannotHideOtherUnsettledActions() throws Exception {
    try (var parent = b1Parent(new B1Spec().edit4().nativeMode("drift-auth", 1, 0))) {
      b1AwaitDriftCapture(parent.id);
      INCREMENTAL_ACK_RELEASE.get(parent.id).countDown();
      awaitFinalizing(parent.id);
      JsonNode receipt =
          C.parse(
              jdbc.queryForObject(
                  "SELECT document::text FROM studio_guided_no_invocation_receipts"
                      + " WHERE session_id=?",
                  String.class,
                  parent.id));
      assertThat(receipt.path("phase").asText()).isEqualTo("ADMITTED_PRE_INVOCATION");
      JsonNode spent = b1SpentAttempt(parent.id);
      assertThat(spent.path("state").asText()).isEqualTo("FAILED");
      assertThat(spent.path("outcomeCode").asText()).isEqualTo("TARGET_CHANGED");
      assertThat(spent.path("dispatchCount").asInt()).isEqualTo(1);
      assertThat(spent.path("attemptOrdinal").asInt()).isZero();
      assertThat(spent.path("admission").path("admissionId"))
          .isEqualTo(receipt.path("admissionId"));
      assertThat(spent.path("preparationId")).isEqualTo(receipt.path("preparationId"));
      assertThat(
              jdbc.queryForObject(
                  "SELECT count(*) FROM studio_guided_obligation_admissions WHERE session_id=?"
                      + " AND admission_id=? AND attempt_ordinal=0",
                  Integer.class,
                  parent.id,
                  receipt.path("admissionId").asText()))
          .isEqualTo(1);
      assertThat(b1NativeCount(parent.id, receipt.path("admissionId").asText(), "NATIVE_ENTER"))
          .isZero();
      var bases = ownedApplicationContext.getBean(GuidedPublicationBaseRepository.class);
      var evidence = ownedApplicationContext.getBean(GuidedPublicationEvidenceRepository.class);
      var builder = new GuidedPlanBuilder(C);
      sessions.transaction(
          () -> {
            var base = bases.find(parent.id).orElseThrow();
            var current = bases.lockCurrent(parent.test);
            var raw = evidence.read(parent.id);
            JsonNode session = sessions.lock(parent.id).document();
            JsonNode provenance = builder.learningProvenance(raw.document().path("sourceManifest"));
            ObjectNode basis = builder.basis(base, current, raw, session, provenance);
            JsonNode excluded = basis.path("incrementalEvidence").path("excludedAttempts");
            assertThat(excluded).hasSize(1);
            assertThat(excluded.get(0).path("action").path("ledger")).isEqualTo(spent);
            assertThat(excluded.get(0).path("preparation").path("preparationId"))
                .isEqualTo(receipt.path("preparationId"));
            assertThat(excluded.get(0).path("obligationAssociation").path("admissionId"))
                .isEqualTo(receipt.path("admissionId"));
            assertThat(basis.path("incrementalEvidence").path("driftReceipt")).isEqualTo(receipt);
            // Disclosed substitution boundary (pure-tier companion): only the returned read copy
            // changes; the stored rows stay immutable and the HTTP/PG rows above stay primary.
            java.util.function.Consumer<java.util.function.Consumer<ObjectNode>> refuses =
                mutation -> {
                  ObjectNode copy = raw.document().deepCopy();
                  mutation.accept(copy);
                  assertThatThrownBy(
                          () ->
                              builder.basis(
                                  base,
                                  current,
                                  new PublicationContracts.Evidence(copy),
                                  session,
                                  provenance))
                      .isInstanceOf(GuidedSessionException.class)
                      .hasMessage("EVIDENCE_MISMATCH");
                };
            var text = JSON.getNodeFactory();
            var joins = new java.util.LinkedHashMap<String, JsonNode>();
            joins.put("workerId", text.textNode("foreign-worker"));
            joins.put("ownerFence", text.numberNode(receipt.path("ownerFence").asInt() + 1));
            joins.put("contextId", text.textNode("foreign-context"));
            joins.put(
                "contextRevision", text.numberNode(receipt.path("contextRevision").asInt() + 1));
            joins.put("requestDigest", text.textNode("0".repeat(64)));
            joins.put("operationHash", text.textNode("0".repeat(64)));
            joins.put("preparationId", text.textNode("foreign-preparation"));
            joins.put("admissionId", text.textNode("foreign-admission"));
            joins.put("evidenceHash", text.textNode("0".repeat(64)));
            for (var join : joins.entrySet()) {
              refuses.accept(
                  copy -> b1SubstituteReceipt(copy, r -> r.set(join.getKey(), join.getValue())));
            }
            refuses.accept(
                copy ->
                    b1SubstituteReceipt(
                        copy,
                        r ->
                            r.put("phase", "PRE_ADMISSION")
                                .putNull("admissionId")
                                .putNull("preparationId")));
            ObjectNode successful = (ObjectNode) raw.document().path("actions").get(0);
            for (String state : List.of("FAILED", "UNKNOWN_OUTCOME", "DISPATCHING")) {
              refuses.accept(
                  copy -> {
                    ObjectNode extra =
                        successful
                            .deepCopy()
                            .put("state", state)
                            .put(
                                "outcomeCode",
                                state.equals("DISPATCHING")
                                    ? "PENDING"
                                    : state.equals("FAILED") ? "TIMEOUT" : "ACK_LOST");
                    extra.putNull("assertionPassed");
                    ((ArrayNode) copy.path("actions")).add(extra);
                  });
            }
            return null;
          });
      int model = MODEL_WIRE.size();
      int effects = RECEIPTS.size();
      int navigations = NAVIGATIONS.get();
      JsonNode merged =
          publicCall(
              "/api/v1/studio/guided-sessions/" + parent.id + "/finalize",
              C.object()
                  .put("schemaVersion", 3)
                  .put("expectedSourceRevision", parent.edited.path("sourceRevision").asText())
                  .put(
                      "expectedConfigurationRevision",
                      parent.edited.path("configurationRevision").asText()),
              200,
              UUID.randomUUID().toString());
      assertThat(MODEL_WIRE).hasSize(model);
      assertThat(RECEIPTS).hasSize(effects);
      assertThat(NAVIGATIONS.get()).isEqualTo(navigations);
      JsonNode artifact =
          C.parse(
              jdbc.queryForObject(
                  "SELECT artifact::text FROM ui_test_revisions WHERE id=?",
                  String.class,
                  UUID.fromString(merged.path("revisionId").asText())));
      assertThat(artifact.path("learnedPlan").path("reusedFrom")).hasSize(1);
    }
  }

  /**
   * B1B-05 (OPEN matrix rows DONE-BOUNDARY, DONE-NOT-PENDING, REFRESH): the BOUNDARY switch records
   * the completed admissions; a continuation committed while pending and released after the switch
   * adds nothing; the prefix confirmation refresh commits once and, with F2 fixed, its carrying
   * /plans call succeeds with no committedRefresh STALE_GENERATION.
   */
  @Test
  void incrementalPrefixContinuationMatrixDoneAndRefreshRows() throws Exception {
    try (var parent = b1Parent(new B1Spec().edit4())) {
      var pause = B1Cut.arm(B1Cut.Kind.ADMIT_COMMIT, parent.id, b1Coordinate(2, 0), 0);
      assertThat(pause.entered.await(45, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
      String key = "b1b-done-race-" + UUID.randomUUID();
      var held = B1Cut.arm(B1Cut.Kind.PLAN_CONTINUATION_COMMIT, parent.id, null, key, 0);
      // GuidedTranslationStore.state requires an actual transaction (RUNTIME_INCOMPATIBLE).
      long planRevision =
          sessions.transaction(() -> plans.state(parent.id).path("planRevision").asLong());
      var command =
          C.object()
              .put("schemaVersion", 3)
              .put("sessionId", parent.id)
              .put("expectedSourceRevision", parent.edited.path("sourceRevision").asText())
              .put(
                  "expectedConfigurationRevision",
                  parent.edited.path("configurationRevision").asText())
              .put("expectedPlanRevision", planRevision);
      long fence = parent.fence();
      try (var pool = java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()) {
        var reply =
            pool.submit(
                () -> {
                  var request =
                      HttpRequest.newBuilder(
                              URI.create(
                                  "https://localhost:"
                                      + port
                                      + "/internal/v2/studio/guided-sessions/"
                                      + parent.id
                                      + "/plans"))
                          .timeout(Duration.ofSeconds(60))
                          .header(
                              "Authorization",
                              "Bearer "
                                  + token(
                                      "backend-controller",
                                      "controller-1",
                                      "studio-guided-controller"))
                          .header("X-Owner-Fence", Long.toString(fence))
                          .header("Idempotency-Key", key)
                          .header("Content-Type", "application/json")
                          .POST(HttpRequest.BodyPublishers.ofString(command.toString()))
                          .build();
                  return HttpClient.newBuilder()
                      .sslContext(TLS)
                      .build()
                      .send(request, HttpResponse.BodyHandlers.ofString());
                });
        assertThat(held.entered.await(20, java.util.concurrent.TimeUnit.SECONDS))
            .as("B committed its continuation while pending")
            .isTrue();
        assertThat(sessions.transaction(() -> sessions.incremental().pending(parent.id))).isTrue();
        pause.release.countDown();
        b1AwaitRow(
            "SELECT count(*) FROM studio_guided_relearn_switches WHERE session_id=?",
            parent.id,
            Duration.ofSeconds(30));
        var switched =
            jdbc.queryForMap(
                "SELECT reason,effective_step_index,next_ordinal,completed_admissions::text AS done"
                    + " FROM studio_guided_relearn_switches WHERE session_id=?",
                parent.id);
        assertThat(switched.get("reason")).isEqualTo("BOUNDARY");
        assertThat(((Number) switched.get("effective_step_index")).intValue()).isEqualTo(3);
        assertThat(((Number) switched.get("next_ordinal")).intValue()).isZero();
        ArrayNode expected = C.object().putArray("items");
        for (JsonNode action :
            sessions.transaction(() -> sessions.incremental().program(parent.id)).path("actions")) {
          expected.add(
              jdbc.queryForObject(
                  "SELECT admission_id FROM studio_guided_actions WHERE session_id=?"
                      + " AND document->'coordinate'=?::jsonb AND attempt_ordinal=0",
                  String.class,
                  parent.id,
                  action.path("coordinate").toString()));
        }
        assertThat(C.parse((String) switched.get("done"))).isEqualTo(expected);
        int requests = b1Count("studio_guided_prefix_requests", parent.id);
        String prefixRows = b1PrefixRows(parent.id);
        held.release.countDown();
        assertThat(reply.get(30, java.util.concurrent.TimeUnit.SECONDS).statusCode())
            .isEqualTo(202);
        assertThat(b1Count("studio_guided_prefix_requests", parent.id)).isEqualTo(requests);
        assertThat(b1PrefixRows(parent.id)).isEqualTo(prefixRows);
        assertThat(b1Count("studio_guided_relearn_switches", parent.id)).isEqualTo(1);
        // openapi readGuidedResult: a running (unpublished) session is pending publication = 202.
        JsonNode running =
            publicCall("/api/v1/studio/guided-sessions/" + parent.id + "/result", null, 202, null);
        assertThat(running.path("publication").path("status").asText()).isEqualTo("PENDING");
        assertThat(running.path("relearnedFrom")).isEqualTo(C.object().put("stepId", b1Step(3)));
        assertThat(pause.failure).isNull();
        assertThat(held.failure).isNull();
      }
    }
    try (var parent =
        b1Parent(
            new B1Spec()
                .ready(5)
                .policy(
                    "CLARIFY_FIRST",
                    com.citi.put.checks.studio.support.ObservedPublicationFixture
                        .DEFAULT_DESTRUCTIVE_VOCABULARY)
                .nativeMode("b1b-refresh", 4, 0))) {
      JsonNode question = b1AwaitQuestion(parent.id);
      JsonNode marker =
          sessions.transaction(
              () -> sessions.lock(parent.id).progress().path("sideEffectConfirmation").deepCopy());
      JsonNode asked = b1PrefixRequest(parent.id, marker.path("prefixRequestDigest").asText());
      int diagnostics = FINALIZE_DIAGNOSTICS.get();
      int effects = RECEIPTS.size();
      publicCall(
          "/api/v1/studio/guided-sessions/" + parent.id + "/clarify",
          b1Answer(question),
          202,
          UUID.randomUUID().toString());
      b1AwaitSucceeded(parent.id, 4, Duration.ofSeconds(45));
      assertThat(b1Commands(parent.id, "observation-refresh")).isEqualTo(1);
      assertThat(
              jdbc.queryForObject(
                  "SELECT idempotency_key FROM studio_guided_commands WHERE namespace=?"
                      + " AND route='observation-refresh'",
                  String.class,
                  parent.id))
          .isEqualTo("prefix-confirmation-" + question.path("clarificationId").asText());
      assertThat(b1Commands(parent.id, "observation-refresh-result")).isEqualTo(1);
      // F2 fixed (qa-d1-review01 §2.3): the /plans call that carries the refresh succeeds. The
      // production success status is 202 Accepted (GuidedPlanningController.plan).
      var carrying =
          B1_PLANS.getOrDefault(parent.id, List.of()).stream()
              .filter(call -> call.refreshCommitted)
              .toList();
      assertThat(carrying).as("exactly one /plans call committed the refresh").hasSize(1);
      assertThat(carrying.getFirst().status).isEqualTo(202);
      assertThat(
              b1Diagnostics(
                  diagnostics, "STALE_GENERATION", B1A_SESSION_SERVICE + "#committedRefresh"))
          .as("F2: no committedRefresh STALE_GENERATION")
          .isZero();
      var submitRequests =
          jdbc.queryForList(
              "SELECT document::text FROM studio_guided_prefix_requests WHERE session_id=?"
                  + " AND step_id=? AND ordinal=0",
              String.class,
              parent.id,
              b1Step(4));
      assertThat(submitRequests).hasSize(2);
      JsonNode submit = b1ActionDocument(parent.id, 4, 0);
      assertThat(submit.path("evidenceHash")).isNotEqualTo(asked.path("evidenceHash"));
      assertThat(submit.path("dispatchCount").asInt()).isEqualTo(1);
      assertThat(RECEIPTS).hasSize(effects + 1);
      b1AwaitRow(
          "SELECT count(*) FROM studio_guided_relearn_switches WHERE session_id=?",
          parent.id,
          Duration.ofSeconds(45));
      assertThat(b1AttemptsBeforeSwitch(parent.id)).isZero();
    }
  }

  /**
   * B1C-01 (ledger 26): a real step-2 assertion failure in the prefix stops the session factually;
   * both gateways stay at zero, nothing is relearned or published, and the original failing
   * assertion is retained as recorded.
   */
  @Test
  void incrementalStepTwoAssertionFailureIsFactualAndNeverRelearned() throws Exception {
    try (var parent =
        b1Parent(
            new B1Spec()
                .text(
                    1,
                    "Enter that order reference in Destination and check Order reference contains"
                        + " that order reference.")
                .edit4()
                .mixedDom("b1c-assert2")
                .nativeMode("b1c-assert2", 1, 1))) {
      JsonNode result = b1AwaitTerminal(parent.id, Duration.ofSeconds(45));
      assertThat(parent.state()).isEqualTo("FAILED");
      assertThat(result.path("relearnedFrom").isNull()).isTrue();
      assertThat(result.path("learnedFromThisRun").asBoolean()).isFalse();
      assertThat(result.path("publication").path("status").asText()).isEqualTo("REFUSED");
      assertThat(MODEL_WIRE).hasSize(parent.modelBefore);
      assertThat(LEGACY_MODEL_CALLS.get()).isEqualTo(parent.legacyBefore);
      assertThat(b1Count("studio_guided_model_attempts", parent.id)).isZero();
      b1AssertNeverDrift(parent.id);
      assertThat(b1Count("studio_guided_suffix_acceptances", parent.id)).isZero();
      assertThat(b1Revisions(parent.test)).isEqualTo(1);
      assertThat(
              jdbc.queryForObject(
                  "SELECT confirmed_revision_id::text FROM ui_tests WHERE id=?",
                  String.class,
                  parent.test))
          .isEqualTo(parent.baseRevision);
      var failed =
          sessions.transaction(() -> sessions.actions(parent.id)).stream()
              .filter(a -> !a.path("state").asText().equals("SUCCEEDED"))
              .toList();
      assertThat(failed).hasSize(1);
      JsonNode assertion = failed.getFirst();
      assertThat(assertion.path("coordinate")).isEqualTo(b1Coordinate(1, 1));
      assertThat(assertion.path("state").asText()).isEqualTo("FAILED");
      assertThat(assertion.path("outcomeCode").asText()).isEqualTo("ASSERTION_FAILED");
      assertThat(
              assertion.path("assertionPassed").isBoolean()
                  && !assertion.path("assertionPassed").asBoolean())
          .isTrue();
      assertThat(assertion.path("dispatchCount").asInt()).isEqualTo(1);
      assertThat(assertion.path("attemptOrdinal").asInt()).isZero();
      JsonNode programAction = null;
      for (JsonNode action :
          sessions.transaction(() -> sessions.incremental().program(parent.id)).path("actions")) {
        if (action.path("coordinate").equals(assertion.path("coordinate"))) {
          programAction = action;
        }
      }
      assertThat(programAction).isNotNull();
      assertThat(assertion.path("operationHash")).isEqualTo(programAction.path("operationHash"));
      assertThat(
              b1NativeCount(
                  parent.id,
                  assertion.path("admission").path("admissionId").asText(),
                  "NATIVE_COMPLETED"))
          .isEqualTo(1);
      for (int index = 2; index < 10; index++) {
        assertThat(
                jdbc.queryForObject(
                    "SELECT count(*) FROM studio_guided_actions WHERE session_id=? AND step_id=?",
                    Integer.class,
                    parent.id,
                    b1Step(index)))
            .isZero();
      }
    }
  }

  /**
   * B1C-02 (ledger 27): a prefix origin redirect, a navigation click-away and a password-policy
   * refusal each stop the run with no model call or publication and are never labelled target
   * drift. F3: no observation callback of the case carries an unapproved origin, and the actual
   * terminal label is recorded value-free for the PO/architect wording ruling.
   */
  @Test
  void incrementalPrefixPolicyRefusalsNeverBecomeDrift() throws Exception {
    for (String variant : List.of("b1c-redirect", "b1c-navigate-away")) {
      boolean redirect = variant.equals("b1c-redirect");
      var spec = new B1Spec().mixedDom(variant).nativeMode("b1c-policy", redirect ? 0 : 4, 0);
      if (redirect) {
        spec.edit4();
      } else {
        spec.ready(6);
      }
      try (var parent = b1Parent(spec)) {
        JsonNode result = b1AwaitTerminal(parent.id, Duration.ofSeconds(60));
        String state = parent.state();
        b1RecordTerminalLabel("B1C-02", variant, parent.id);
        assertThat(state).as(variant).isIn("FAILED", "UNKNOWN_OUTCOME");
        b1AssertNeverDrift(parent.id);
        b1AssertApprovedObservationOrigins(parent.id, parent.base);
        assertThat(result.path("relearnedFrom").isNull()).isTrue();
        assertThat(result.path("learnedFromThisRun").asBoolean()).isFalse();
        assertThat(MODEL_WIRE).hasSize(parent.modelBefore);
        assertThat(LEGACY_MODEL_CALLS.get()).isEqualTo(parent.legacyBefore);
        assertThat(b1Count("studio_guided_model_attempts", parent.id)).isZero();
        assertThat(b1Revisions(parent.test)).isEqualTo(1);
        if (redirect) {
          assertThat(B1_REDIRECTS.get())
              .as("one real redirect, never a second navigation")
              .isEqualTo(1);
          assertThat(NAVIGATIONS.get()).isEqualTo(parent.navigationsBefore + 1);
          assertThat(b1DispatchedOnce(parent.id, 0)).isEqualTo(1);
        } else {
          assertThat(b1DispatchedOnce(parent.id, 4)).isEqualTo(1);
          assertThat(RECEIPTS)
              .as("the replaced handler never submits")
              .hasSize(parent.effectsBefore);
        }
      }
    }
    // Password policy: the OBS-007 secret prefix replays against two live password controls.
    p3Case(
        () -> {
          p3Mode = P3Mode.LOGIN;
          p3Grant(primaryCsi, "fixture");
          UUID test = p3CreateSource(primaryCsi, "fixture", true);
          VaultScope scope = VaultScope.of(primaryCsi, "fixture", test);
          p3Seed(scope, p3ExpectedPassword);
          String original = p3Start(test, "fixture");
          awaitFinalizing(original);
          P3Publication base = p3Publish(original);
          // Reuse the reviewed two-control page phase (p4GuidedAdversarialPasswordCount) after
          // the same owned-resource cleanup p4PositiveNativeControl performs before a new phase.
          p3CleanupOwnedResources();
          p3OwnedGuidedCookies.clear();
          p3OwnedOrdinaryCookies.clear();
          p4AssertRepositoryGraph();
          P4_WITNESS_FAILED.set(false);
          p4StartObserverPhase(2);
          int reads =
              COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS");
          int model = MODEL_WIRE.size();
          int legacy = LEGACY_MODEL_CALLS.get();
          P3_RECEIPTS.clear();
          ObjectNode start =
              p3StartCommand(test, "fixture")
                  .put("baseRevisionId", base.revision().toString())
                  .put("firstLearnStepId", THREE);
          String mixed =
              p3Call(p3Cookie, "/api/v1/studio/guided-sessions", start, 202)
                  .path("session")
                  .path("sessionId")
                  .asText();
          JsonNode result = b1AwaitTerminal(mixed, Duration.ofSeconds(60));
          b1RecordTerminalLabel("B1C-02", "password-policy", mixed);
          assertThat(
                  sessions.transaction(
                      () -> sessions.lock(mixed).document().path("state").asText()))
              .isEqualTo("FAILED");
          b1AssertNeverDrift(mixed);
          assertThat(result.path("relearnedFrom").isNull()).isTrue();
          assertThat(
                  COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS"))
              .isEqualTo(reads);
          assertThat(P3_RECEIPTS).isEmpty();
          assertThat(P4_PASSWORD_WRITES.get()).as("no secret dispatch").isZero();
          assertThat(MODEL_WIRE).hasSize(model);
          assertThat(LEGACY_MODEL_CALLS.get()).isEqualTo(legacy);
          assertThat(b1Revisions(test)).isEqualTo(1);
        });
  }

  /**
   * B1C-03 (ledger 80; ledger 82 fresh post-answer guard clause): after a valid CLARIFY_FIRST
   * consent the fresh prefix proposal re-runs the actual guards; a governed multi-word destructive
   * phrase is denied before effect, while a valid authored Enter is retained.
   */
  @Test
  void incrementalFreshPostConsentGuardsDenyDangerousProposals() throws Exception {
    var vocabulary =
        new ArrayList<>(
            com.citi.put.checks.studio.support.ObservedPublicationFixture
                .DEFAULT_DESTRUCTIVE_VOCABULARY);
    vocabulary.addAll(List.of("save all", "delete all", "archive all"));
    var hostileIds = new ArrayList<String>();
    String allowedId = null;
    for (String step6 :
        List.of(
            "Click all, then Save",
            "Click all, then Delete",
            "Press Enter in all notes to Archive",
            "Press Enter in Destination")) {
      boolean allowed = step6.equals("Press Enter in Destination");
      try (var parent =
          b1Parent(
              new B1Spec()
                  .guards()
                  .text(5, step6)
                  .ready(6)
                  .policy("CLARIFY_FIRST", vocabulary)
                  .nativeMode("b1c-guards", 5, 0))) {
        if (allowed) {
          allowedId = parent.id;
        } else {
          hostileIds.add(parent.id);
        }
        JsonNode question = b1AwaitQuestion(parent.id);
        assertThat(question.path("reason").asText()).isEqualTo("SIDE_EFFECT_CONFIRMATION");
        assertThat(question.path("coordinate").path("stepId").asText()).isEqualTo(b1Step(4));
        JsonNode marker =
            sessions.transaction(
                () ->
                    sessions.lock(parent.id).progress().path("sideEffectConfirmation").deepCopy());
        JsonNode asked = b1PrefixRequest(parent.id, marker.path("prefixRequestDigest").asText());
        publicCall(
            "/api/v1/studio/guided-sessions/" + parent.id + "/clarify",
            b1Answer(question),
            202,
            UUID.randomUUID().toString());
        if (allowed) {
          b1AwaitRow(
              "SELECT count(*) FROM studio_guided_relearn_switches WHERE session_id=?",
              parent.id,
              Duration.ofSeconds(60));
          JsonNode press = b1ActionDocument(parent.id, 5, 0);
          assertThat(press.path("state").asText()).isEqualTo("SUCCEEDED");
          assertThat(press.path("dispatchCount").asInt()).isEqualTo(1);
          assertThat(
                  b1NativeCount(
                      parent.id,
                      press.path("admission").path("admissionId").asText(),
                      "NATIVE_COMPLETED"))
              .isEqualTo(1);
          assertThat(b1Commands(parent.id, "clarify")).as("no second question").isEqualTo(1);
          continue;
        }
        JsonNode result = b1AwaitTerminal(parent.id, Duration.ofSeconds(60));
        assertThat(parent.state()).isEqualTo("FAILED");
        JsonNode submit = b1ActionDocument(parent.id, 4, 0);
        assertThat(submit.path("state").asText()).isEqualTo("SUCCEEDED");
        assertThat(submit.path("dispatchCount").asInt()).isEqualTo(1);
        assertThat(submit.path("evidenceHash"))
            .as("fresh post-answer proposal; the guards re-ran")
            .isNotEqualTo(asked.path("evidenceHash"));
        JsonNode progress =
            sessions.transaction(() -> sessions.lock(parent.id).progress().deepCopy());
        assertThat(progress.path("errorCode").asText()).isEqualTo("POLICY_DENIED");
        assertThat(b1AuditRefusals(parent.id, "DESTRUCTIVE_VERB")).isEqualTo(1);
        assertThat(
                jdbc.queryForObject(
                    "SELECT count(*) FROM studio_guided_actions WHERE session_id=? AND step_id=?",
                    Integer.class,
                    parent.id,
                    b1Step(5)))
            .isZero();
        assertThat(
                b1Native(parent.id).stream()
                    .filter(e -> e.path("stepId").asText().equals(b1Step(5)))
                    .toList())
            .isEmpty();
        assertThat(b1Count("studio_guided_model_attempts", parent.id)).isZero();
        assertThat(MODEL_WIRE).hasSize(parent.modelBefore);
        b1AssertNeverDrift(parent.id);
        assertThat(result.path("relearnedFrom").isNull()).isTrue();
        assertThat(b1Revisions(parent.test)).isEqualTo(1);
        JsonNode confirmed = progress.path("sideEffectConfirmation");
        var keys = new java.util.HashSet<String>();
        confirmed.fieldNames().forEachRemaining(keys::add);
        assertThat(keys).isEqualTo(Set.of("clarificationId", "prefixRequestDigest", "status"));
        assertThat(confirmed.path("status").asText()).isEqualTo("CONFIRMED");
        String digest = confirmed.path("prefixRequestDigest").asText();
        assertThat(
                publicCall("/api/v1/studio/guided-sessions/" + parent.id, null, 200, null)
                    .toString())
            .doesNotContain(digest);
        assertThat(result.toString()).doesNotContain(digest);
        assertThat(MODEL_WIRE.stream().noneMatch(wire -> wire.contains(digest))).isTrue();
      }
    }
    // qa-rulings01 R1: authoritative exactness over the whole invocation's audit window (the
    // tally plants this method by name and cannot key the four parents separately).
    var refusals = guidedActionRefusalsSinceTallyStart();
    String message = "B1C-03 plants exactly one DESTRUCTIVE_VERB refusal per hostile parent";
    assertThat(refusals).as(message).hasSize(3);
    assertThat(refusals)
        .as(message)
        .allSatisfy(fields -> assertThat(fields.get("reasonCode")).isEqualTo("DESTRUCTIVE_VERB"));
    var refusedSessions = refusals.stream().map(fields -> fields.get("sessionId")).toList();
    assertThat(hostileIds).as(message).hasSize(3);
    assertThat(refusedSessions)
        .as(message)
        .hasSize(3)
        .containsExactlyInAnyOrderElementsOf(hostileIds);
    assertThat(allowedId).isNotNull();
    assertThat(refusedSessions).as(message).doesNotContain(allowedId);
  }

  /**
   * B1C-04 (ledger 81; ledger 82 direct-admit regate): while the S(4) question waits, an
   * unconfirmed direct admit, a real refresh and a real context delivery change nothing and the
   * answer is accepted once; a real worker stall lets the owner lease lapse naturally, after which
   * the answer is refused and cancellation wins with no late effect or new browser.
   */
  @Test
  void incrementalWaitingAnswerRejectsChangedContextGenerationAndNaturalLeaseExpiry()
      throws Exception {
    var spec =
        new B1Spec()
            .ready(5)
            .policy(
                "CLARIFY_FIRST",
                com.citi.put.checks.studio.support.ObservedPublicationFixture
                    .DEFAULT_DESTRUCTIVE_VOCABULARY)
            .nativeMode("b1c-wait", 4, 0);
    try (var parent = b1Parent(spec)) {
      JsonNode question = b1AwaitQuestion(parent.id);
      assertThat(question.path("reason").asText()).isEqualTo("SIDE_EFFECT_CONFIRMATION");
      assertThat(MODEL_WIRE).hasSize(parent.modelBefore);
      var controller =
          com.citi.put.checks.studio.guided.session.GuidedInternalIdentityFixture.controller();
      var service =
          ownedApplicationContext.getBean(
              com.citi.put.checks.studio.guided.session.GuidedSessionService.class);
      var bridge =
          ownedApplicationContext.getBean(
              com.citi.put.checks.studio.guided.bridge.GuidedDispatchService.class);
      long fence = parent.fence();
      JsonNode progress =
          sessions.transaction(() -> sessions.lock(parent.id).progress().deepCopy());
      String pending = incrementalPendingSnapshot(parent.id);
      String immutable = incrementalImmutableSnapshot(parent.id);
      // 82: an unconfirmed direct internal admit (the confirmIncrementalPrefix body construction).
      JsonNode request =
          b1PrefixRequest(
              parent.id,
              progress.path("sideEffectConfirmation").path("prefixRequestDigest").asText());
      JsonNode target = null;
      for (JsonNode node : progress.path("observation").path("nodes")) {
        if (node.path("name").asText().equals("Submit")) {
          target = node;
        }
      }
      assertThat(target).isNotNull();
      JsonNode current = sessions.transaction(() -> sessions.lock(parent.id).document().deepCopy());
      ObjectNode direct =
          C.object()
              .put("schemaVersion", 3)
              .put("sessionId", parent.id)
              .put("scopeHash", current.path("scopeHash").asText())
              .put("generation", progress.path("generation").asInt())
              .put("evidenceHash", progress.path("evidenceHash").asText());
      direct.set("coordinate", request.path("coordinate"));
      direct.set("executionEvidence", progress.path("executionEvidence"));
      direct
          .put("contextRevision", request.path("contextRevision").asInt())
          .put("authoredInputsHash", request.path("authoredInputsHash").asText());
      direct
          .putObject("target")
          .put("nodeId", target.path("nodeId").asText())
          .put("documentId", progress.path("documentId").asText())
          .put("generation", progress.path("generation").asInt())
          .putObject("locator")
          .put("kind", "role")
          .put("role", target.path("role").asText())
          .put("name", "Submit")
          .put("exact", true);
      direct.putObject("operation").put("kind", "click");
      assertThat(
              incrementalControllerProbe(parent.id, fence, direct, 409, "admissions")
                  .path("code")
                  .asText())
          .isEqualTo("STALE_GENERATION");
      // 81: a real generation change attempt while waiting.
      ObjectNode refresh =
          new com.citi.put.checks.studio.guided.bridge.GuidedMaterializationService(jdbc, C)
              .identity(service.runnerContext(controller, parent.id, fence));
      refresh.put("expectedGeneration", progress.path("generation").asInt());
      assertThatThrownBy(
              () ->
                  bridge.observe(
                      controller,
                      parent.id,
                      fence,
                      "b1c-wait-refresh-" + UUID.randomUUID(),
                      refresh))
          .isInstanceOf(GuidedSessionException.class)
          .hasMessage("STALE_GENERATION");
      assertThat(b1Commands(parent.id, "observation-refresh")).isZero();
      // 81: a real context delivery while waiting changes nothing.
      int versionsBefore = b1Count("studio_guided_materialization_versions", parent.id);
      int revisionBefore = b1MaterializationRevision(parent.id);
      JsonNode identity = bridge.pushContext(controller, parent.id, fence);
      assertThat(identity.path("contextRevision")).isEqualTo(request.path("contextRevision"));
      assertThat(b1Count("studio_guided_materialization_versions", parent.id))
          .isEqualTo(versionsBefore);
      assertThat(b1MaterializationRevision(parent.id)).isEqualTo(revisionBefore);
      JsonNode after = sessions.transaction(() -> sessions.lock(parent.id).progress().deepCopy());
      for (String field : List.of("generation", "documentId", "evidenceHash", "observationHash")) {
        assertThat(after.path(field)).isEqualTo(progress.path(field));
      }
      assertThat(incrementalPendingSnapshot(parent.id)).isEqualTo(pending);
      assertThat(incrementalImmutableSnapshot(parent.id)).isEqualTo(immutable);
      int effects = RECEIPTS.size();
      publicCall(
          "/api/v1/studio/guided-sessions/" + parent.id + "/clarify",
          b1Answer(question),
          202,
          UUID.randomUUID().toString());
      b1AwaitSucceeded(parent.id, 4, Duration.ofSeconds(45));
      assertThat(RECEIPTS).hasSize(effects + 1);
    }
    try (var parent = b1Parent(spec)) {
      JsonNode question = b1AwaitQuestion(parent.id);
      int navigations = NAVIGATIONS.get();
      int effects = RECEIPTS.size();
      int model = MODEL_WIRE.size();
      String pending = incrementalPendingSnapshot(parent.id);
      b1StallWorker();
      b1AwaitNaturalLeaseExpiry(parent.id);
      assertThat(parent.state())
          .as("no graceful LEASE_LOST lifecycle committed")
          .isEqualTo("AWAITING_CLARIFICATION");
      String key = UUID.randomUUID().toString();
      for (int i = 0; i < 2; i++) {
        assertThat(
                publicCall(
                        "/api/v1/studio/guided-sessions/" + parent.id + "/clarify",
                        b1Answer(question),
                        409,
                        key)
                    .path("code")
                    .asText())
            .isEqualTo("STALE_FENCE");
      }
      assertThat(incrementalPendingSnapshot(parent.id)).isEqualTo(pending);
      assertThat(
              jdbc.queryForObject(
                  "SELECT count(*) FROM studio_guided_actions WHERE session_id=? AND step_id=?",
                  Integer.class,
                  parent.id,
                  b1Step(4)))
          .isZero();
      b1ResumeWorker();
      Thread.sleep(3000);
      assertThat(parent.state())
          .as("the late runner lifecycle cannot act on an expired lease")
          .isEqualTo("AWAITING_CLARIFICATION");
      parent.cancel();
      assertThat(parent.state()).isEqualTo("CANCELLED");
      p3AwaitTeardown(parent.id);
      assertThat(NAVIGATIONS.get()).as("no new browser").isEqualTo(navigations);
      assertThat(RECEIPTS).as("no late effect").hasSize(effects);
      assertThat(MODEL_WIRE).hasSize(model);
      assertThat(
              jdbc.queryForObject(
                  "SELECT count(*) FROM studio_guided_actions WHERE session_id=?"
                      + " AND (attempt_ordinal<>0 OR document->>'state'='UNKNOWN_OUTCOME')",
                  Integer.class,
                  parent.id))
          .isZero();
      assertThat(
              b1Native(parent.id).stream()
                  .filter(e -> e.path("stepId").asText().equals(b1Step(4)))
                  .toList())
          .isEmpty();
    }
  }

  /**
   * B1D-01 (ledger 55): an explicit-first-step EMPTY_PREFIX session carries the exact empty program
   * pair in its initial context, its real rebootstrap and every later delivery; a direct half,
   * changed, reforged or omitted pair is refused; a no-base ordinary session omits the pair.
   */
  @Test
  void incrementalEmptyPrefixProgramPairSurvivesEveryContextDelivery() throws Exception {
    try (var parent = b1Parent(new B1Spec().ready(0).pairLog(true).nativeMode("b1d-empty", 0, 0))) {
      var plan =
          jdbc.queryForMap(
              "SELECT initial_step_index,prefix_program::text AS program,prefix_program_hash"
                  + " FROM studio_guided_relearn_plans WHERE session_id=?",
              parent.id);
      JsonNode program = C.parse((String) plan.get("program"));
      String programHash = (String) plan.get("prefix_program_hash");
      assertThat(((Number) plan.get("initial_step_index")).intValue()).isZero();
      assertThat(program.path("actions")).isEmpty();
      assertThat(program.path("sourceStepIds")).isEmpty();
      assertThat(GuidedContracts.hash(program)).isEqualTo(programHash);
      assertThat(
              jdbc.queryForObject(
                  "SELECT reason FROM studio_guided_relearn_switches WHERE session_id=?",
                  String.class,
                  parent.id))
          .isEqualTo("EMPTY_PREFIX");
      var cut = B1Cut.arm(B1Cut.Kind.ADMIT_COMMIT, parent.id, b1Coordinate(0, 0), 0);
      assertThat(cut.entered.await(90, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
      assertThat(cut.failure).isNull();
      var controller =
          com.citi.put.checks.studio.guided.session.GuidedInternalIdentityFixture.controller();
      long fence = parent.fence();
      ObjectNode authentic =
          ownedApplicationContext
              .getBean(com.citi.put.checks.studio.guided.session.GuidedSessionService.class)
              .runnerContext(controller, parent.id, fence);
      assertThat(authentic.path("prefixProgramHash").asText()).isEqualTo(programHash);
      long acceptedBefore = b1PairPhases(parent.id, "UPDATE_ACCEPTED");
      var probes = new java.util.LinkedHashMap<String, ObjectNode>();
      ObjectNode half = authentic.deepCopy();
      half.remove("prefixProgramHash");
      probes.put("SCHEMA", half);
      ObjectNode changed = authentic.deepCopy();
      ((ObjectNode) changed.path("prefixProgram")).putArray("sourceStepIds").add(b1Step(0));
      changed.put("prefixProgramHash", GuidedContracts.hash(changed.path("prefixProgram")));
      probes.put("INPUT_IDENTITY:changed", changed);
      probes.put(
          "INPUT_IDENTITY:reforged", authentic.deepCopy().put("prefixProgramHash", "0".repeat(64)));
      ObjectNode omitted = authentic.deepCopy();
      omitted.remove("prefixProgram");
      omitted.remove("prefixProgramHash");
      probes.put("INPUT_IDENTITY:omitted", omitted);
      for (var probe : probes.entrySet()) {
        var reply = b1RunnerContextProbe(parent.id, fence, probe.getValue());
        assertThat(reply.statusCode()).as(probe.getKey()).isEqualTo(409);
        assertThat(C.parse(reply.body()).path("code").asText())
            .as(probe.getKey())
            .isEqualTo(probe.getKey().split(":")[0]);
      }
      assertThat(b1PairPhases(parent.id, "UPDATE_ACCEPTED"))
          .as("no probe was accepted")
          .isEqualTo(acceptedBefore);
      cut.release.countDown();
      awaitFinalizing(parent.id);
      var mixed = b1PairEvents(parent.id);
      var phases = mixed.stream().map(r -> r.path("phase").asText()).toList();
      assertThat(phases.stream().filter("START"::equals).count()).isEqualTo(1);
      assertThat(phases).contains("START_HELD", "START_RELEASED");
      for (JsonNode row : mixed) {
        if (!List.of("START", "START_HELD", "START_RELEASED", "UPDATE_ACCEPTED")
            .contains(row.path("phase").asText())) {
          continue;
        }
        assertThat(row.path("hasProgram").asBoolean() && row.path("hasHash").asBoolean())
            .as(row.toString())
            .isTrue();
        assertThat(row.path("programActions").asInt(-1)).isZero();
        assertThat(row.path("programSteps").asInt(-1)).isZero();
        assertThat(row.path("programHashValid").asBoolean()).isTrue();
        assertThat(row.path("prefixProgramHash").asText()).isEqualTo(programHash);
      }
      assertThat(phases.stream().filter("UPDATE_ACCEPTED"::equals).count())
          .as("rebootstrap + later deliveries")
          .isGreaterThanOrEqualTo(2);
      JsonNode bootstrap =
          sessions.transaction(
              () -> sessions.lock(parent.id).progress().path("translationBootstrap").deepCopy());
      // GuidedTranslationService.bootstrapStage(READY) replaces the CONTEXT_PENDING marker, so its
      // deliveries[] never survives READY; the committed beginBootstrapDelivery results do.
      assertThat(bootstrap.path("phase").asText()).isEqualTo("READY");
      JsonNode ack = bootstrap.path("metadataAcknowledgement");
      List<B1BootstrapDelivery> deliveries = List.copyOf(B1_BOOTSTRAP_DELIVERIES);
      assertThat(deliveries).as("rebootstrap: two committed mixed-session deliveries").hasSize(2);
      assertThat(deliveries.stream().map(B1BootstrapDelivery::deliveryId).distinct().count())
          .as("two distinct delivery ids")
          .isEqualTo(2);
      for (B1BootstrapDelivery delivery : deliveries) {
        assertThat(delivery.identityHash()).isEqualTo(ack.path("identityHash").asText());
        assertThat(delivery.contextHash())
            .as("the same pending context was re-delivered")
            .isEqualTo(ack.path("contextHash").asText());
      }
      assertThat(ack.path("deliveryId").asText())
          .isEqualTo(deliveries.get(1).deliveryId())
          .isNotEqualTo(deliveries.get(0).deliveryId());
      for (String metadata :
          jdbc.queryForList(
              "SELECT context_metadata::text FROM studio_guided_materialization_deliveries"
                  + " WHERE session_id=? AND context_metadata IS NOT NULL",
              String.class,
              parent.id)) {
        JsonNode issued = C.parse(metadata);
        assertThat(issued.path("prefixProgram")).isEqualTo(program);
        assertThat(issued.path("prefixProgramHash").asText()).isEqualTo(programHash);
      }
      var base = b1PairEvents(parent.base);
      assertThat(base).isNotEmpty();
      assertThat(b1Count("studio_guided_relearn_plans", parent.base)).isZero();
      for (JsonNode row : base) {
        assertThat(row.path("hasProgram").asBoolean() || row.path("hasHash").asBoolean())
            .as(row.toString())
            .isFalse();
      }
    }
  }

  /**
   * B1D-02 (ledger 56): BOUNDARY and EMPTY_PREFIX results report the entered boundary after the
   * switch even when the later SOURCE_PLAN fails; before the switch relearnedFrom is null; the
   * failed result is not learned or published and contradictory results fail the contract.
   */
  @Test
  void incrementalBoundaryAndEmptyPrefixPlanningFailureKeepEnteredBoundary() throws Exception {
    try (var parent = b1Parent(new B1Spec().edit4().mixedDom("b1d-boundary-plan-fail"))) {
      var cut = B1Cut.arm(B1Cut.Kind.ADMIT_COMMIT, parent.id, b1Coordinate(2, 0), 0);
      assertThat(cut.entered.await(45, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
      assertThat(b1Count("studio_guided_relearn_switches", parent.id)).isZero();
      // openapi readGuidedResult: held mid-prefix the session is pending publication = 202.
      JsonNode before =
          publicCall("/api/v1/studio/guided-sessions/" + parent.id + "/result", null, 202, null);
      assertThat(before.has("relearnedFrom") && before.path("relearnedFrom").isNull()).isTrue();
      assertThat(before.path("learnedFromThisRun").asBoolean()).isFalse();
      assertThat(before.path("publication").path("status").asText()).isEqualTo("PENDING");
      cut.release.countDown();
      JsonNode failed = b1AwaitTerminal(parent.id, Duration.ofSeconds(60));
      assertThat(
              jdbc.queryForObject(
                  "SELECT reason FROM studio_guided_relearn_switches WHERE session_id=?",
                  String.class,
                  parent.id))
          .isEqualTo("BOUNDARY");
      assertThat(failed.path("relearnedFrom")).isEqualTo(C.object().put("stepId", b1Step(3)));
      b1AssertFailedResult(parent, failed);
      assertThat(cut.failure).isNull();
    }
    try (var parent = b1Parent(new B1Spec().ready(0).mixedDom("b1d-empty-plan-fail"))) {
      // Unheld: the read may land before or after the SOURCE_PLAN failure, so the status is
      // checked against the projected publication status (PENDING = 202, otherwise 200).
      JsonNode entered = b1ResultPerContract(parent.id);
      assertThat(entered.path("relearnedFrom")).isEqualTo(C.object().put("stepId", b1Step(0)));
      JsonNode failed = b1AwaitTerminal(parent.id, Duration.ofSeconds(60));
      assertThat(
              jdbc.queryForObject(
                  "SELECT reason FROM studio_guided_relearn_switches WHERE session_id=?",
                  String.class,
                  parent.id))
          .isEqualTo("EMPTY_PREFIX");
      assertThat(failed.path("relearnedFrom")).isEqualTo(C.object().put("stepId", b1Step(0)));
      b1AssertFailedResult(parent, failed);
    }
  }

  // ---- B1 instruments (b1bcd-design01 T1-T7) ----------------------------------------------------

  private static final List<B1Cut> B1_CUTS = new CopyOnWriteArrayList<>();
  private static final ThreadLocal<B1PlansCall> B1_PLANS_CALL = new ThreadLocal<>();
  private static final java.util.concurrent.ConcurrentMap<String, List<B1PlansCall>> B1_PLANS =
      new java.util.concurrent.ConcurrentHashMap<>();
  private static final java.util.concurrent.ConcurrentMap<String, List<String>>
      B1_OBSERVED_ORIGINS = new java.util.concurrent.ConcurrentHashMap<>();

  /**
   * Committed translation-bootstrap deliveries in commit order (value-free: id and hashes only).
   * Cleared right before the mixed-session start, because scopeHash is shared with the base session
   * (new22-qa-ack01 §2.2), so only the mixed session's deliveries are ever listed.
   */
  private static final List<B1BootstrapDelivery> B1_BOOTSTRAP_DELIVERIES =
      new CopyOnWriteArrayList<>();

  private record B1BootstrapDelivery(String deliveryId, String identityHash, String contextHash) {}

  private static final AtomicInteger B1_REDIRECTS = new AtomicInteger();
  private static final String B1_INTERNAL = "/internal/v2/studio/guided-sessions/";
  private static final String B1_UNAPPROVED = "https://unapproved.invalid/b1c";
  private static final String B1_SUBMIT_HANDLER =
      "document.getElementById('done').hidden=false;fetch('/receipt',{method:'POST',"
          + "body:document.getElementById('destination').value});";
  private static volatile boolean b1Recording;
  private static volatile boolean b1GuardsPage;
  private static volatile Process b1StalledWorker;

  /** One internal /plans request of an armed session: its key, final status and refresh commit. */
  private static final class B1PlansCall {
    final String key;
    volatile boolean refreshCommitted;
    volatile int status;

    B1PlansCall(String key) {
      this.key = key;
    }
  }

  private record B1Probe(
      JsonNode body,
      String bearer,
      SSLContext tls,
      long fence,
      String path,
      int status,
      String code) {}

  /** T1: request-entry and outermost-commit holds; at most two cuts are armed at once. */
  private static final class B1Cut {
    enum Kind {
      PLANS_ENTRY,
      ADMIT_COMMIT,
      CONSUME_COMMIT,
      PLAN_CONTINUATION_COMMIT
    }

    final Kind kind;
    final String sessionId;
    final String requestKey;
    final JsonNode coordinate;
    final int plansOrdinal;
    final java.util.concurrent.CountDownLatch entered = new java.util.concurrent.CountDownLatch(1);
    final java.util.concurrent.CountDownLatch release = new java.util.concurrent.CountDownLatch(1);
    final AtomicInteger selections = new AtomicInteger();
    final AtomicInteger plansSeen = new AtomicInteger();
    volatile String admissionId;
    volatile String ledgerState;
    volatile long enteredAtNanos;
    volatile Throwable failure;

    private B1Cut(
        Kind kind, String sessionId, JsonNode coordinate, String requestKey, int plansOrdinal) {
      this.kind = kind;
      this.sessionId = sessionId;
      this.coordinate = coordinate;
      this.requestKey = requestKey;
      this.plansOrdinal = plansOrdinal;
    }

    static B1Cut arm(Kind kind, String sessionId, JsonNode coordinate, int plansOrdinal) {
      return arm(kind, sessionId, coordinate, null, plansOrdinal);
    }

    static B1Cut arm(
        Kind kind, String sessionId, JsonNode coordinate, String requestKey, int plansOrdinal) {
      assertThat(c5Capture).as("B1 cuts never overlap C5 sampling").isNull();
      assertThat(b1aCallbackCut).as("B1 cuts never overlap the B1a cut").isNull();
      assertThat(B1_CUTS.size()).isLessThan(2);
      var cut = new B1Cut(kind, sessionId, coordinate, requestKey, plansOrdinal);
      B1_CUTS.add(cut);
      return cut;
    }

    boolean plansRequest(jakarta.servlet.http.HttpServletRequest http) {
      return "POST".equals(http.getMethod())
          && http.getRequestURI().equals(B1_INTERNAL + sessionId + "/plans");
    }

    void onPlansRequest() {
      if (kind == Kind.PLANS_ENTRY
          && plansSeen.incrementAndGet() >= plansOrdinal
          && selections.getAndIncrement() == 0) {
        hold("PLANS_ENTRY");
      }
    }

    private boolean selects(Object result) {
      B1PlansCall call = B1_PLANS_CALL.get();
      JsonNode won = b1WonLedger(result);
      return switch (kind) {
        case ADMIT_COMMIT ->
            result instanceof ObjectNode action
                && sessionId.equals(action.path("sessionId").asText())
                && "ADMITTED".equals(action.path("state").asText())
                && coordinate.equals(action.path("coordinate"))
                && b1OnStack(B1A_SESSION_SERVICE, "admitChecked");
        case CONSUME_COMMIT ->
            won != null
                && sessionId.equals(won.path("sessionId").asText())
                && coordinate.equals(won.path("coordinate"));
        case PLAN_CONTINUATION_COMMIT ->
            result == null
                && call != null
                && requestKey.equals(call.key)
                && b1DirectPlanContinuation();
        case PLANS_ENTRY -> false;
      };
    }

    void afterOutermostCommit(Object result) {
      try {
        if (!selects(result) || selections.getAndIncrement() != 0) {
          return;
        }
        // Observe the typed ledger only; a consumed capability is never saved, cloned or resent.
        JsonNode won = b1WonLedger(result);
        JsonNode ledger = won != null ? won : result instanceof ObjectNode action ? action : null;
        if (ledger != null) {
          admissionId = ledger.path("admission").path("admissionId").asText();
          ledgerState = ledger.path("state").asText();
        }
      } catch (RuntimeException | AssertionError observerFailure) {
        failure = observerFailure;
        return;
      }
      hold(kind.name());
    }

    private void hold(String phase) {
      enteredAtNanos = System.nanoTime();
      entered.countDown();
      try {
        if (!release.await(30, java.util.concurrent.TimeUnit.SECONDS)) {
          failure = new IllegalStateException("B1 cut deadline " + phase);
        }
      } catch (InterruptedException interrupted) {
        Thread.currentThread().interrupt();
        failure = interrupted;
      }
    }
  }

  /** The ledger of an actual WonConsumption result, or null; the capability is never touched. */
  private static JsonNode b1WonLedger(Object result) {
    return result
            instanceof
            com.citi.put.checks.studio.guided.session.GuidedSessionService.WonConsumption won
        ? won.ledger()
        : null;
  }

  /** RuntimeHooks seam gate: armed only while a B1 parent records or a B1 cut is armed. */
  private static boolean b1Armed() {
    return b1Recording || !B1_CUTS.isEmpty();
  }

  /** Runs after an actual outermost commit with no transaction active; never alters the result. */
  private static void b1AfterCommit(Object result) {
    B1PlansCall call = B1_PLANS_CALL.get();
    if (call != null
        && result != null
        && b1OnStack(B1A_SESSION_SERVICE, "committedObservationRefresh")) {
      call.refreshCommitted = true;
    }
    // B1D-01: an actual committed bootstrap delivery (value-free: id and hashes, read only).
    if (b1Recording
        && result instanceof ObjectNode delivery
        && delivery.hasNonNull("deliveryId")
        && delivery.has("identity")
        && delivery.has("context")
        && b1OnStack(B1A_TRANSLATION + "GuidedTranslationService", "beginBootstrapDelivery")) {
      B1_BOOTSTRAP_DELIVERIES.add(
          new B1BootstrapDelivery(
              delivery.path("deliveryId").asText(),
              GuidedContracts.hash(delivery.path("identity")),
              GuidedContracts.hash(delivery.path("context"))));
    }
    for (B1Cut cut : B1_CUTS) {
      cut.afterOutermostCommit(result);
    }
  }

  private static boolean b1OnStack(String cls, String method) {
    return StackWalker.getInstance()
        .walk(
            frames ->
                frames.anyMatch(
                    f -> f.getClassName().startsWith(cls) && f.getMethodName().equals(method)));
  }

  /** The plan() continuation transaction only; never bootstrap, advancePrefix or a helper. */
  private static boolean b1DirectPlanContinuation() {
    return StackWalker.getInstance()
        .walk(
            stream -> {
              var frames = stream.map(f -> f.getClassName() + "#" + f.getMethodName()).toList();
              for (int at = 0; at < frames.size(); at++) {
                if (!frames.get(at).startsWith(B1A_SESSION_SERVICE)
                    || !frames.get(at).endsWith("#translationTransaction")) {
                  continue;
                }
                for (int next = at + 1; next < frames.size(); next++) {
                  if (frames.get(next).startsWith(B1A_SESSION_SERVICE)) {
                    continue; // proxy frames
                  }
                  return frames.get(next).equals(B1A_TRANSLATION + "GuidedTranslationService#plan");
                }
              }
              return false;
            });
  }

  @FunctionalInterface
  private interface B1Chain {
    void proceed(jakarta.servlet.ServletRequest request)
        throws IOException, jakarta.servlet.ServletException;
  }

  /** Filter seam gate: POST /plans and /observations of guided sessions while B1 is armed. */
  private static boolean b1Selected(jakarta.servlet.http.HttpServletRequest http) {
    if (!b1Armed() || !"POST".equals(http.getMethod())) {
      return false;
    }
    String uri = http.getRequestURI();
    return uri.startsWith(B1_INTERNAL) && (uri.endsWith("/plans") || uri.endsWith("/observations"));
  }

  /**
   * Records each /plans call (key, final status, whether it committed an observation refresh) and
   * each /observations callback origin, and applies an armed PLANS_ENTRY hold. The original request
   * continues unchanged; only an /observations body is read through a caching wrapper.
   */
  private static void b1Filter(
      jakarta.servlet.http.HttpServletRequest http,
      jakarta.servlet.ServletResponse response,
      B1Chain chain)
      throws IOException, jakarta.servlet.ServletException {
    String uri = http.getRequestURI();
    String id = uri.substring(B1_INTERNAL.length(), uri.lastIndexOf('/'));
    if (uri.endsWith("/observations")) {
      var wrapped = new org.springframework.web.util.ContentCachingRequestWrapper(http, 4194304);
      try {
        chain.proceed(wrapped);
      } finally {
        String origin = "UNPARSED";
        try {
          JsonNode body =
              C.parse(new String(wrapped.getContentAsByteArray(), StandardCharsets.UTF_8));
          if (body.path("observation").path("origin").isTextual()) {
            origin = body.path("observation").path("origin").asText();
          }
        } catch (RuntimeException unparsed) {
          origin = "UNPARSED";
        }
        B1_OBSERVED_ORIGINS
            .computeIfAbsent(id, ignored -> new CopyOnWriteArrayList<>())
            .add(origin);
      }
      return;
    }
    var call = new B1PlansCall(http.getHeader("Idempotency-Key"));
    B1_PLANS_CALL.set(call);
    try {
      for (B1Cut cut : B1_CUTS) {
        if (cut.plansRequest(http)) {
          cut.onPlansRequest();
        }
      }
      chain.proceed(http);
    } finally {
      B1_PLANS_CALL.remove();
      call.status = ((jakarta.servlet.http.HttpServletResponse) response).getStatus();
      B1_PLANS.computeIfAbsent(id, ignored -> new CopyOnWriteArrayList<>()).add(call);
    }
  }

  /** T3: a real server redirect for the mixed redirect variant; Chromium's route guard decides. */
  private static boolean b1FlowRedirect(com.sun.net.httpserver.HttpExchange exchange)
      throws IOException {
    if (!"b1c-redirect".equals(incrementalDomVariant)) {
      return false;
    }
    B1_REDIRECTS.incrementAndGet();
    exchange.getResponseHeaders().set("Location", B1_UNAPPROVED);
    exchange.sendResponseHeaders(302, -1);
    exchange.close();
    return true;
  }

  /** T3: base-time guard controls and mixed-only page variants; inert unless a B1 parent arms. */
  private static String b1FlowPage(String html) {
    String page = html;
    if ("b1c-assert2"
        .equals(incrementalDomVariant)) { // the same real post-write mutation as assert-fail (D5-1)
      page =
          page.replace(
              "</body>",
              "<script>document.getElementById('destination').addEventListener('change',()=>{"
                  + "document.querySelector('output[aria-label=\"Order reference\"]').textContent="
                  + "'changed-after-read';});</script></body>");
    } else if ("b1c-navigate-away".equals(incrementalDomVariant)) {
      // The whole Submit handler is replaced, so no /receipt request can race the navigation.
      if (!page.contains(B1_SUBMIT_HANDLER)) {
        throw new IllegalStateException("B1 navigate-away fixture handler missing");
      }
      page = page.replace(B1_SUBMIT_HANDLER, "location.assign('" + B1_UNAPPROVED + "');");
    }
    if (b1GuardsPage) {
      page =
          page.replace(
              "<button id='submit'>",
              "<button id='saveall'>Save all</button><button id='deleteall'>Delete all</button>"
                  + "<label for='notes'>Archive all notes</label><textarea id='notes'></textarea>"
                  + "<button id='submit'>");
    }
    return page;
  }

  /** T4: the B1C-01 step 2 authors a fill and then a binding containsText assertion. */
  private static boolean b1StepTwoAssertion(JsonNode step) {
    return step.path("text").asText().contains("check Order reference contains");
  }

  /** T4: the B1C-03 guard step obligation; null for every other authored step. */
  private static ObjectNode b1GuardObligation(String stepId, JsonNode step) {
    String text = step.path("text").asText();
    if (text.startsWith("Click all, then ")) {
      return obligation(
          stepId, 0, "click", text.endsWith("Save") ? "Save all" : "Delete all", null, null);
    }
    if (text.startsWith("Press Enter in ")) {
      return obligation(
          stepId,
          0,
          "press",
          text.contains("all notes") ? "Archive all notes" : "Destination",
          null,
          null);
    }
    return null;
  }

  private static String b1Step(int index) {
    return INCREMENTAL_STEPS.get(index);
  }

  private static ObjectNode b1Coordinate(int index, int ordinal) {
    return C.object().put("stepId", b1Step(index)).put("ordinal", ordinal);
  }

  private static List<String> b1BaseTexts() {
    var texts = new ArrayList<String>();
    texts.add("Open " + URL + " and read the Order reference.");
    texts.add(
        "Enter that order reference in Destination (an authored alternative is literal-control).");
    texts.add("Check Destination has that order reference.");
    texts.add("Check Destination is visible.");
    texts.add("Click Submit and check Confirmation appears.");
    for (int i = 5; i < 10; i++) {
      texts.add("Check Confirmation is visible at checkpoint " + (i + 1) + ".");
    }
    return texts;
  }

  /** T2: closed lawful recipe: authored text, governed policy, fixture page and observer mode. */
  private static final class B1Spec {
    final List<String> texts = b1BaseTexts();
    boolean edit4;
    Integer readyFirst;
    String stance;
    String mixedDom;
    String nativeMode;
    List<String> vocabulary;
    boolean guardsPage;
    boolean pairLog;
    boolean holdEmptyStart;
    int nativeStep;
    int nativeOrdinal;

    B1Spec text(int index, String value) {
      texts.set(index, value);
      return this;
    }

    /** The PFXSYNC edit: step 4 gains " Verify it remains visible." (prefixSyncEdit). */
    B1Spec edit4() {
      edit4 = true;
      return this;
    }

    B1Spec ready(int firstIndex) {
      readyFirst = firstIndex;
      return this;
    }

    B1Spec policy(String stance, List<String> vocabulary) {
      this.stance = stance;
      this.vocabulary = vocabulary;
      return this;
    }

    B1Spec mixedDom(String variant) {
      mixedDom = variant;
      return this;
    }

    B1Spec guards() {
      guardsPage = true;
      return this;
    }

    B1Spec pairLog(boolean holdEmptyStart) {
      pairLog = true;
      this.holdEmptyStart = holdEmptyStart;
      return this;
    }

    B1Spec nativeMode(String mode, int stepIndex, int ordinal) {
      nativeMode = mode;
      nativeStep = stepIndex;
      nativeOrdinal = ordinal;
      return this;
    }
  }

  private final class B1Parent implements AutoCloseable {
    final UUID test;
    final String base;
    final String id;
    final String baseRevision;
    final JsonNode edited;
    final int navigationsBefore;
    final int effectsBefore;
    final int modelBefore;
    final int legacyBefore;

    B1Parent(
        UUID test, String base, String id, String baseRevision, JsonNode edited, int[] counters) {
      this.test = test;
      this.base = base;
      this.id = id;
      this.baseRevision = baseRevision;
      this.edited = edited;
      this.navigationsBefore = counters[0];
      this.effectsBefore = counters[1];
      this.modelBefore = counters[2];
      this.legacyBefore = counters[3];
    }

    long fence() {
      return sessions.transaction(
          () -> sessions.lock(id).document().path("owner").path("fence").asLong());
    }

    String state() {
      return sessions.transaction(() -> sessions.lock(id).document().path("state").asText());
    }

    void cancel() throws Exception {
      if (!List.of(
              "SUCCEEDED",
              "FAILED",
              "UNKNOWN_OUTCOME",
              "CANCELLED",
              "EXPIRED",
              "PUBLICATION_CONFLICT")
          .contains(state())) {
        publicCall(
            "/api/v1/studio/guided-sessions/" + id + "/cancel",
            C.object().put("schemaVersion", 3).put("reason", "userRequested"),
            202,
            UUID.randomUUID().toString());
      }
    }

    @Override
    public void close() throws Exception {
      var failures = new ArrayList<Throwable>();
      try {
        b1ResumeWorker();
      } catch (Exception | AssertionError failure) {
        failures.add(failure);
      }
      for (B1Cut cut : B1_CUTS) {
        cut.release.countDown();
      }
      var held = INCREMENTAL_ACK_RELEASE.remove(id);
      if (held != null) {
        held.countDown();
      }
      INCREMENTAL_DRIFT_CAPTURE.remove(id);
      INCREMENTAL_ACK_ENTERED.remove(id);
      coreRole = "owner";
      forgetCachedCoreIdentity();
      try {
        refreshFixtureCredentials();
        cancel();
      } catch (Exception | AssertionError failure) {
        failures.add(failure);
      }
      try {
        p3AwaitTeardown(id);
      } catch (Exception | AssertionError failure) {
        failures.add(failure);
      }
      for (B1Cut cut : B1_CUTS) {
        if (cut.failure != null) {
          failures.add(new AssertionError("B1 " + cut.kind + " cut failure", cut.failure));
        }
      }
      try {
        b1ResetInstruments();
      } catch (Exception | AssertionError failure) {
        failures.add(failure);
      }
      throwTeardownFailures(failures);
    }
  }

  /** Clears every B1 arming; safe to call when nothing is armed. */
  private void b1ResetInstruments() throws Exception {
    B1_CUTS.forEach(cut -> cut.release.countDown());
    B1_CUTS.clear();
    try {
      Files.writeString(TEMP.resolve("obs015-native-mode.json"), "{}");
      b1WritePairControl(C.object());
    } finally {
      b1Recording = false;
      B1_BOOTSTRAP_DELIVERIES.clear();
      incrementalTenScenario = false;
      incrementalDomVariant = null;
      b1GuardsPage = false;
      primaryCsi = "CSI-123";
      forgetCachedCoreIdentity();
    }
  }

  /** T2: lawful ten-step base, public finalize, optional edit/policy, then the mixed start. */
  private B1Parent b1Parent(B1Spec spec) throws Exception {
    assertThat(B1_CUTS).isEmpty();
    assertThat(PREFIX_SYNC_CUTS).isEmpty();
    assertThat(b1aCallbackCut).isNull();
    B1Parent parent = null;
    try {
      // Per-case CSI isolation (as P3/PFXSYNC/B1a): never enlarge the real daily cap.
      primaryCsi = "CSI-B1-" + (++p3CsiOrdinal);
      forgetCachedCoreIdentity();
      jdbc.update(
          "INSERT INTO csi_systems(id,name,business_unit,criticality,owner_email,environment)"
              + " VALUES (?,'Orders','Ops','HIGH','fixture@example.invalid','Production')",
          primaryCsi);
      startWorkers();
      seedGovernedPolicies(primaryCsi);
      Files.writeString(TEMP.resolve("obs015-native-mode.json"), "{}");
      B1_PLANS.clear();
      B1_OBSERVED_ORIGINS.clear();
      B1_REDIRECTS.set(0);
      incrementalTenScenario = true;
      incrementalDomVariant = null;
      b1GuardsPage = spec.guardsPage;
      b1Recording = true;
      b1WritePairControl(
          spec.pairLog
              ? C.object()
                  .put("armed", true)
                  .put("holdEmptyStartMs", spec.holdEmptyStart ? 16000 : 0)
              : C.object());
      b1PrivateWrite(TEMP.resolve("obs015-prefix-sync-b1-pair-events.jsonl"), "");
      AUDIT_CANARIES.addAll(spec.texts);
      AUDIT_CANARIES.addAll(
          List.of(
              "Operations",
              "Order reference",
              "Destination",
              "Submit",
              "Confirmation",
              "literal-control"));
      var steps = new ArrayList<AuthoringStep>();
      for (int i = 0; i < 10; i++) {
        steps.add(new AuthoringStep(UUID.fromString(b1Step(i)), spec.texts.get(i), null));
      }
      var authoring = new AuthoringV2Request(2, null, steps);
      UUID test = UUID.randomUUID();
      jdbc.update(
          "INSERT INTO ui_tests(id,name,csi_id,environment,browser,steps,variables,authoring,"
              + "authoring_revision_inputs,created_by,created_at,updated_at) VALUES"
              + " (?,'B1 incremental',?,'fixture','chromium',?::jsonb,'[]'::jsonb,?::jsonb,"
              + "?::jsonb,'fixture@example.invalid',now(),now())",
          test,
          primaryCsi,
          JSON.writeValueAsString(spec.texts),
          JSON.writeValueAsString(authoring),
          JSON.writeValueAsString(AuthoringRevisionIdentity.create(authoring, Map.of())));
      String original = startLearning(test);
      awaitFinalizing(original);
      JsonNode base =
          publicCall(
              "/api/v1/studio/guided-sessions/" + original + "/finalize",
              C.object()
                  .put("schemaVersion", 3)
                  .put("expectedSourceRevision", "1")
                  .put("expectedConfigurationRevision", "1"),
              200,
              UUID.randomUUID().toString());
      p3AwaitTeardown(original);
      JsonNode edited = publicCall("/api/v1/studio/tests/" + test, null, 200, null);
      assertThat(edited.path("readiness").asText()).isEqualTo("READY");
      if (spec.edit4) {
        edited = prefixSyncEdit(test, spec.texts.get(3) + " Verify it remains visible.");
        assertThat(edited.path("firstChangedStepId").asText()).isEqualTo(b1Step(3));
      }
      if (spec.stance != null) {
        b1Policy(primaryCsi, spec.stance, spec.vocabulary);
      }
      Files.writeString(
          TEMP.resolve("obs015-native-mode.json"),
          spec.nativeMode == null
              ? "{}"
              : C.object()
                  .put("mode", spec.nativeMode)
                  .put("stepId", b1Step(spec.nativeStep))
                  .put("ordinal", spec.nativeOrdinal)
                  .toString());
      Files.writeString(TEMP.resolve("obs015-native-events.jsonl"), "");
      ObjectNode start =
          C.object()
              .put("schemaVersion", 3)
              .put("testId", test.toString())
              .put("sourceRevision", edited.path("sourceRevision").asText())
              .put("configurationRevision", edited.path("configurationRevision").asText())
              .put("environmentId", "fixture")
              .put("applicationId", "orders")
              .put("baseRevisionId", base.path("revisionId").asText());
      if (spec.readyFirst != null) {
        start.put("firstLearnStepId", b1Step(spec.readyFirst));
      }
      start.set("versions", versions());
      incrementalDomVariant = spec.mixedDom;
      int[] counters = {
        NAVIGATIONS.get(), RECEIPTS.size(), MODEL_WIRE.size(), LEGACY_MODEL_CALLS.get()
      };
      // new22-qa-ack01 §2.2: the base session shares scopeHash; list mixed deliveries only.
      B1_BOOTSTRAP_DELIVERIES.clear();
      String id =
          publicCall("/api/v1/studio/guided-sessions", start, 202, UUID.randomUUID().toString())
              .path("session")
              .path("sessionId")
              .asText();
      parent = new B1Parent(test, original, id, base.path("revisionId").asText(), edited, counters);
      return parent;
    } catch (Exception | AssertionError failure) {
      if (parent == null) {
        // startLearning tracks original sessions for the existing failure-safe @AfterEach cleanup.
        try {
          b1ResetInstruments();
        } catch (Exception | AssertionError cleanup) {
          failure.addSuppressed(cleanup);
        }
      }
      throw failure;
    }
  }

  /** A new approved governed version via the production repository (mirrors ensurePolicy). */
  private void b1Policy(String csi, String stance, List<String> vocabulary) {
    var repository =
        new com.citi.put.checks.studio.guided.policy.ObservationPolicyRepository(jdbc, C);
    ObjectNode submitted = C.object().put("schemaVersion", 3).put("sideEffectStance", stance);
    var origins = submitted.putArray("allowedOrigins");
    POLICY.path("allowedOrigins").forEach(origins::add);
    submitted.set("applicationPolicy", POLICY.path("applicationPolicy").deepCopy());
    if (vocabulary != null) {
      var words = submitted.putArray("destructiveVocabulary");
      vocabulary.forEach(words::add);
    }
    ObjectNode document =
        com.citi.put.checks.studio.guided.policy.ObservationPolicyDocuments.materialize(
            C,
            submitted,
            com.citi.put.checks.studio.support.ObservedPublicationFixture
                .DEFAULT_DESTRUCTIVE_VOCABULARY);
    String documentHash =
        com.citi.put.checks.studio.guided.policy.ObservationPolicyDocuments.documentHash(document);
    String observationHash =
        com.citi.put.checks.studio.guided.policy.ObservationPolicyDocuments.observationPolicyHash(
            document);
    sessions.transaction(
        () -> {
          var state = repository.state(csi, "orders", "fixture").orElseThrow();
          repository.lock(state.policyId());
          int next = repository.latestVersion(state.policyId()) + 1;
          repository.insertVersion(
              state.policyId(),
              next,
              document,
              documentHash,
              observationHash,
              com.citi.put.checks.studio.support.ObservedPublicationFixture.POLICY_AUTHOR);
          repository.insertApproval(
              state.policyId(),
              next,
              com.citi.put.checks.studio.support.ObservedPublicationFixture.POLICY_APPROVER,
              "b1-approval-" + next);
          return null;
        });
  }

  /** Owner-only (0600) write of a B1 sink file; it is collected by the prefix-sync inventory. */
  private static void b1PrivateWrite(Path file, String content) throws Exception {
    if (!Files.exists(file, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
      Files.createFile(
          file,
          java.nio.file.attribute.PosixFilePermissions.asFileAttribute(
              java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")));
    }
    assertThat(Files.isSymbolicLink(file)).isFalse();
    Files.writeString(file, content, StandardCharsets.UTF_8);
    Files.setPosixFilePermissions(
        file, java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));
  }

  private static void b1WritePairControl(JsonNode value) throws Exception {
    String canonical = GuidedContracts.canonical(value);
    assertThat(canonical.getBytes(StandardCharsets.UTF_8).length).isLessThanOrEqualTo(4096);
    b1PrivateWrite(TEMP.resolve("obs015-prefix-sync-b1-pair-control.json"), canonical);
  }

  private static List<JsonNode> b1PairEvents(String sessionId) throws Exception {
    Path file = TEMP.resolve("obs015-prefix-sync-b1-pair-events.jsonl");
    assertThat(Files.size(file)).isLessThanOrEqualTo(65536);
    String hash = GuidedContracts.hash(JSON.getNodeFactory().textNode(sessionId));
    var rows =
        Files.readAllLines(file, StandardCharsets.UTF_8).stream()
            .filter(line -> !line.isBlank())
            .map(C::parse)
            .toList();
    assertThat(rows.stream().noneMatch(r -> r.path("phase").asText().equals("ERROR"))).isTrue();
    return rows.stream().filter(r -> r.path("sessionHash").asText().equals(hash)).toList();
  }

  private static long b1PairPhases(String sessionId, String phase) throws Exception {
    return b1PairEvents(sessionId).stream()
        .filter(r -> r.path("phase").asText().equals(phase))
        .count();
  }

  /** T6: SIGSTOP of the current owned guided worker only; no clock, lease or cadence change. */
  private void b1StallWorker() throws Exception {
    Process worker = guidedWorker;
    assertThat(worker).isNotNull();
    assertThat(worker.isAlive()).isTrue();
    assertThat(
            OWNED_FIXTURE_PROCESSES.stream()
                .anyMatch(
                    p ->
                        p.process == worker
                            && p.role.equals("guided")
                            && p.generation == ownedGeneration))
        .as("only the current owned guided worker may be stalled")
        .isTrue();
    assertThat(worker.pid()).isNotEqualTo(ProcessHandle.current().pid());
    b1Signal(worker, "-STOP");
    b1StalledWorker = worker;
  }

  private void b1ResumeWorker() throws Exception {
    Process worker = b1StalledWorker;
    if (worker == null) {
      return;
    }
    b1StalledWorker = null;
    if (worker.isAlive()) {
      b1Signal(worker, "-CONT");
    }
  }

  private static void b1Signal(Process worker, String signal) throws Exception {
    var kill =
        new ProcessBuilder("kill", signal, Long.toString(worker.pid()))
            .redirectErrorStream(true)
            .start();
    assertThat(kill.waitFor(5, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
    assertThat(kill.exitValue()).isZero();
  }

  /** Waits for the original owner lease to lapse on both the DB clock and the Java clock. */
  private Instant b1AwaitNaturalLeaseExpiry(String id) throws Exception {
    Thread.sleep(1000); // a renewal already on the wire when the worker stopped may still commit
    JsonNode owner =
        sessions.transaction(() -> sessions.lock(id).document().path("owner").deepCopy());
    Instant lease = Instant.parse(owner.path("leaseExpiresAt").asText());
    long end = System.nanoTime() + Duration.ofSeconds(45).toNanos();
    while (true) {
      JsonNode now =
          sessions.transaction(() -> sessions.lock(id).document().path("owner").deepCopy());
      assertThat(now)
          .as("a stalled owner never renews, re-fences or changes worker")
          .isEqualTo(owner);
      Boolean dbExpired =
          jdbc.queryForObject(
              "SELECT (document->'owner'->>'leaseExpiresAt')::timestamptz < clock_timestamp()"
                  + " FROM studio_guided_sessions WHERE session_id=?",
              Boolean.class,
              id);
      if (Boolean.TRUE.equals(dbExpired) && Instant.now().isAfter(lease)) {
        return lease;
      }
      assertThat(System.nanoTime()).as("original lease must lapse naturally").isLessThan(end);
      Thread.sleep(100);
    }
  }

  private static String b1Token(ObjectNode claims, String alg, boolean sign) throws Exception {
    var encoder = Base64.getUrlEncoder().withoutPadding();
    String unsigned =
        encoder.encodeToString(
                C.object()
                    .put("alg", alg)
                    .put("typ", "JWT")
                    .toString()
                    .getBytes(StandardCharsets.UTF_8))
            + "."
            + encoder.encodeToString(claims.toString().getBytes(StandardCharsets.UTF_8));
    if (!sign) {
      return unsigned + "." + encoder.encodeToString(new byte[] {1});
    }
    Signature signature = Signature.getInstance("SHA256withRSA");
    signature.initSign(ISSUER.getPrivate());
    signature.update(unsigned.getBytes(StandardCharsets.UTF_8));
    return unsigned + "." + encoder.encodeToString(signature.sign());
  }

  /** RS256 to HS256 confusion: HMAC keyed with the deployed public key's encoded bytes. */
  private static String b1HmacConfusionToken(ObjectNode claims) throws Exception {
    var encoder = Base64.getUrlEncoder().withoutPadding();
    String unsigned =
        encoder.encodeToString(
                C.object()
                    .put("alg", "HS256")
                    .put("typ", "JWT")
                    .toString()
                    .getBytes(StandardCharsets.UTF_8))
            + "."
            + encoder.encodeToString(claims.toString().getBytes(StandardCharsets.UTF_8));
    var mac = javax.crypto.Mac.getInstance("HmacSHA256");
    mac.init(new javax.crypto.spec.SecretKeySpec(ISSUER.getPublic().getEncoded(), "HmacSHA256"));
    return unsigned
        + "."
        + encoder.encodeToString(mac.doFinal(unsigned.getBytes(StandardCharsets.UTF_8)));
  }

  private static ObjectNode b1Claims(String role, String subject) {
    long now = Instant.now().getEpochSecond();
    return C.object()
        .put("iss", "fixture-issuer")
        .put("sub", subject)
        .put("aud", "studio-guided-controller")
        .put("role", role)
        .put("exp", now + 299)
        .put("iat", now - 1);
  }

  private static ObjectNode b1Rehash(ObjectNode callback) {
    ObjectNode receipt = (ObjectNode) callback.path("receipt");
    receipt.remove("receiptHash");
    receipt.put("receiptHash", GuidedContracts.hash(receipt));
    return callback;
  }

  /** A copy of the authentic callback with one receipt field changed, then honestly rehashed. */
  private static ObjectNode b1Forge(ObjectNode authentic, String field, JsonNode value) {
    ObjectNode copy = authentic.deepCopy();
    ((ObjectNode) copy.path("receipt")).set(field, value);
    return b1Rehash(copy);
  }

  private SSLContext b1NoClientCertificate() throws Exception {
    var trustStore = KeyStore.getInstance("PKCS12");
    try (var input = Files.newInputStream(TEMP.resolve("trust.p12"))) {
      trustStore.load(input, "fixture".toCharArray());
    }
    var trusts = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
    trusts.init(trustStore);
    var context = SSLContext.getInstance("TLS");
    context.init(null, trusts.getTrustManagers(), null);
    return context;
  }

  private HttpResponse<String> b1RawOutcome(
      String path, long fence, String body, String bearer, SSLContext tls) throws Exception {
    var builder =
        HttpRequest.newBuilder(URI.create("https://localhost:" + port + path))
            .timeout(Duration.ofSeconds(10))
            .header("X-Owner-Fence", Long.toString(fence))
            .header("Idempotency-Key", UUID.randomUUID().toString())
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(body));
    if (bearer != null) {
      builder.header("Authorization", "Bearer " + bearer);
    }
    return HttpClient.newBuilder()
        .sslContext(tls)
        .build()
        .send(builder.build(), HttpResponse.BodyHandlers.ofString());
  }

  /** Controller-authenticated direct runner context probe; negative only. */
  private HttpResponse<String> b1RunnerContextProbe(String id, long fence, JsonNode context)
      throws Exception {
    refreshFixtureCredentials();
    var request =
        HttpRequest.newBuilder(
                URI.create(
                    "https://localhost:"
                        + GUIDED_PORT
                        + "/internal/v2/studio/guided-sessions/"
                        + id
                        + "/context"))
            .timeout(Duration.ofSeconds(10))
            .header(
                "Authorization",
                "Bearer " + Files.readString(TEMP.resolve("controller.jwt")).strip())
            .header("X-Owner-Fence", Long.toString(fence))
            .header("Idempotency-Key", UUID.randomUUID().toString())
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(context.toString()))
            .build();
    return HttpClient.newBuilder()
        .sslContext(TLS)
        .build()
        .send(request, HttpResponse.BodyHandlers.ofString());
  }

