  /** GET /result; the status must be the one its own publication status implies (openapi). */
  private JsonNode b1ResultPerContract(String id) throws Exception {
    var response =
        HttpClient.newBuilder()
            .sslContext(TLS)
            .build()
            .send(
                HttpRequest.newBuilder(
                        URI.create(
                            "https://localhost:"
                                + port
                                + "/api/v1/studio/guided-sessions/"
                                + id
                                + "/result"))
                    .timeout(Duration.ofSeconds(15))
                    .header("Cookie", "put_session=" + COOKIE)
                    .GET()
                    .build(),
                HttpResponse.BodyHandlers.ofString());
    JsonNode result = C.parse(response.body());
    boolean pending = result.path("publication").path("status").asText().equals("PENDING");
    assertThat(response.statusCode()).as(response.body()).isEqualTo(pending ? 202 : 200);
    C.validate("v3/result", result);
    return result;
  }

