  /**
   * w3-d4 (B3B-1): a cancel can win the race against the coordinator's first assignment. Then
   * GuidedSessionService.stop has neither a context nor an assignment to address, writes no
   * teardownStatus and sends nothing: there is no runtime whose stop could be acknowledged. Only
   * when an assignment row exists must the H8 teardown reach CONFIRMED.
   */
  private void b3AwaitCancelSettled(String id) throws Exception {
    assertThat(
            jdbc.queryForObject(
                "SELECT state FROM studio_guided_sessions WHERE session_id=?", String.class, id))
        .as("cancelled before any outcome")
        .isEqualTo("CANCELLED");
    if (neverAssignedSettled(id)) {
      return;
    }
    p3AwaitTeardown(id);
  }

  /**
   * w3-qa-ack02 §6 shared guard (b3AwaitCancelSettled and the failed-test cleanup): one read that
   * is true only for a terminal session that never had a runtime: 0 assignments, 0
   * materializations, no teardownStatus and no teardownRequest. Everything else must reach
   * CONFIRMED.
   */
  private boolean neverAssignedSettled(String id) {
    return Boolean.TRUE.equals(
        jdbc.queryForObject(
            "SELECT s.state IN ('SUCCEEDED','PUBLICATION_CONFLICT','FAILED','UNKNOWN_OUTCOME',"
                + "'CANCELLED','EXPIRED')"
                + " AND NOT EXISTS (SELECT 1 FROM studio_guided_assignments a"
                + " WHERE a.session_id=s.session_id)"
                + " AND NOT EXISTS (SELECT 1 FROM studio_guided_materializations m"
                + " WHERE m.session_id=s.session_id)"
                + " AND COALESCE(s.progress->>'teardownStatus','')=''"
                + " AND s.progress->'teardownRequest' IS NULL"
                + " FROM studio_guided_sessions s WHERE s.session_id=?",
            Boolean.class,
            id));
  }

  /** w3-qa-ack02 §4.3: mirrors GuidedSourceClassifier.safeContext (kind text, non-empty value). */
  private static void b2SafeContext(
      JsonNode context, String stepId, com.fasterxml.jackson.databind.node.ArrayNode result) {
    for (JsonNode entry : context.path("entries")) {
      if (entry.path("kind").asText().equals("text")
          && entry.path("value").isTextual()
          && !entry.path("value").asText().isEmpty()) {
        result.addObject().put("stepId", stepId).put("text", entry.path("value").asText());
      }
    }
  }

